package com.kurenai7968.volume_controller

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.media.AudioManager
import io.flutter.plugin.common.EventChannel

class VolumeListener(private val context: Context, private val audioManager: AudioManager) : EventChannel.StreamHandler {
    private lateinit var volumeBroadcastReceiver: VolumeBroadcastReceiver

    override fun onListen(arguments: Any?, events: EventChannel.EventSink?) {
        val args = arguments as? Map<String, Any>
        val fetchInitialVolume = args?.get(EventArgument.FETCH_INITIAL_VOLUME) as? Boolean ?: false

        volumeBroadcastReceiver = VolumeBroadcastReceiver(events, audioManager)
        context.registerReceiver(volumeBroadcastReceiver, IntentFilter(VOLUME_CHANGED_ACTION))

        if (fetchInitialVolume) {
            events?.success(audioManager.getVolume())
        }
    }

    override fun onCancel(arguments: Any?) {
        context.unregisterReceiver(volumeBroadcastReceiver)
    }
}

class VolumeBroadcastReceiver(private val events: EventChannel.EventSink?, private val audioManager: AudioManager) : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent?) {
        events?.success(audioManager.getVolume())
    }
}

package com.kurenai7968.volume_controller

import android.content.Context
import android.media.AudioManager
import io.flutter.embedding.engine.plugins.FlutterPlugin
import io.flutter.plugin.common.EventChannel
import io.flutter.plugin.common.MethodCall
import io.flutter.plugin.common.MethodChannel
import io.flutter.plugin.common.MethodChannel.MethodCallHandler
import io.flutter.plugin.common.MethodChannel.Result

class VolumeControllerPlugin : FlutterPlugin, MethodCallHandler {
  private lateinit var volumeController: VolumeController
  private lateinit var methodChannel: MethodChannel
  private lateinit var eventChannel: EventChannel

  override fun onAttachedToEngine(flutterPluginBinding: FlutterPlugin.FlutterPluginBinding) {
    val context = flutterPluginBinding.applicationContext
    val audioManager = context.getSystemService(Context.AUDIO_SERVICE) as AudioManager
    val volumeListener = VolumeListener(context, audioManager)
    volumeController = VolumeController(audioManager)

    // Register EventChannel
    eventChannel = EventChannel(flutterPluginBinding.binaryMessenger, ChannelName.EVENT_CHANNEL)
    eventChannel.setStreamHandler(volumeListener)

    // Register MethodChannel
    methodChannel = MethodChannel(flutterPluginBinding.binaryMessenger, ChannelName.METHOD_CHANNEL)
    methodChannel.setMethodCallHandler(this)
  }

  override fun onMethodCall(call: MethodCall, result: Result) {
    when (call.method) {
      MethodName.GET_VOLUME -> {
        val volume = volumeController.getVolume()
        result.success(volume)
      }
      MethodName.SET_VOLUME -> {
        val volume: Double = call.argument(MethodArgument.VOLUME)!!
        val showSystemUI: Boolean = call.argument(MethodArgument.SHOW_SYSTEM_UI)!!

        volumeController.setVolume(volume, showSystemUI)
        result.success(null)
      }
      MethodName.IS_MUTED -> {
        val isMute = volumeController.isMute()
        result.success(isMute)
      }
      MethodName.SET_MUTE -> {
        val isMute: Boolean = call.argument(MethodArgument.IS_MUTE)!!
        val showSystemUI: Boolean = call.argument(MethodArgument.SHOW_SYSTEM_UI)!!

        volumeController.setMute(isMute, showSystemUI)
        result.success(null)
      }
      else -> result.notImplemented()
    }
  }

  override fun onDetachedFromEngine(binding: FlutterPlugin.FlutterPluginBinding) {
    methodChannel.setMethodCallHandler(null)
    eventChannel.setStreamHandler(null)
  }
}

package com.kurenai7968.volume_controller

import android.media.AudioManager
import kotlin.math.round

class VolumeController(private val audioManager: AudioManager) {
    private var tempMuteVolume: Double?

    init {
        tempMuteVolume = null
    }

    fun setVolume(volume: Double, showSystemUI: Boolean) {
        val clampedVolume = volume.coerceIn(0.0, 1.0)
        val maxVolume = audioManager.getStreamMaxVolume(AudioManager.STREAM_MUSIC)
        val adjustedVolume = (round(clampedVolume * maxVolume)).toInt()
        val flag = if (showSystemUI) AudioManager.FLAG_SHOW_UI else 0

        if (clampedVolume != 0.0) {
            tempMuteVolume = null
        }

        audioManager.setStreamVolume(AudioManager.STREAM_MUSIC, adjustedVolume, flag)
    }

    fun getVolume(): Double {
        return audioManager.getVolume()
    }

    fun isMute(): Boolean {
        return getVolume() == 0.0
    }

    fun setMute(isMute: Boolean, showSystemUI: Boolean) {
        if (isMute) {
            tempMuteVolume = getVolume()
            setVolume(0.0, showSystemUI)
        } else {
            val previousVolume = tempMuteVolume ?: return
            setVolume(previousVolume, showSystemUI)
            tempMuteVolume = null
        }
    }
}

