impl Drop for IgnoreInteractionEvents {
    fn drop(&mut self) {
        unsafe {
            let mtm = MainThreadMarker::new().unwrap();
            let application = UIApplication::sharedApplication(mtm);
            #[allow(deprecated)]
            application.endIgnoringInteractionEvents();
        }
    }
}

