use windows::{
    core::PWSTR,
    Win32::{
        Foundation::{HGLOBAL, VARIANT_BOOL},
        Graphics::Imaging::{
            CLSID_WICImagingFactory, GUID_ContainerFormatBmp, GUID_ContainerFormatPng,
            IWICBitmapFrameEncode, IWICImagingFactory, WICBitmapEncoderNoCache,
        },
        System::{
            Com::{
                IStream,
                StructuredStorage::{
                    CreateStreamOnHGlobal, GetHGlobalFromStream, IPropertyBag2, PROPBAG2,
                },
            },
            Memory::{GlobalLock, GlobalSize, GlobalUnlock},
            Variant::{VariantInit, VT_BOOL},
        },
    },
};

use super::common::create_instance;

/// Convert image from input_stream to PNG
pub fn convert_to_png(input_stream: IStream) -> windows::core::Result<Vec<u8>> {
    let factory: IWICImagingFactory = create_instance(&CLSID_WICImagingFactory)?;
    unsafe {
        let decoder =
            factory.CreateDecoderFromStream(&input_stream, null_mut(), Default::default())?;
        let encoder = factory.CreateEncoder(&GUID_ContainerFormatPng, null_mut())?;
        let output_stream = CreateStreamOnHGlobal(HGLOBAL::default(), true)?;
        encoder.Initialize(&output_stream, WICBitmapEncoderNoCache)?;
        let frame = decoder.GetFrame(0)?;
        let mut encoder_frame = Option::<IWICBitmapFrameEncode>::None;
        encoder.CreateNewFrame(&mut encoder_frame as *mut _, null_mut())?;
        let encoder_frame = encoder_frame.unwrap();
        encoder_frame.Initialize(None)?;
        encoder_frame.WriteSource(&frame, std::ptr::null_mut())?;
        encoder_frame.Commit()?;
        encoder.Commit()?;
        let hglobal = GetHGlobalFromStream(&output_stream)?;
        let size = GlobalSize(hglobal);
        let data = GlobalLock(hglobal);
        let v = slice::from_raw_parts(data as *const u8, size);
        let res: Vec<u8> = v.into();
        GlobalUnlock(hglobal).ok();
        // prevent clippy from complaining. want the stream to outlive
        // hglobal
        let _output_stream = output_stream;
        Ok(res)
    }
}

/// Converts image from input stream to CF_DIB or CF_DIBV5 representation.
pub fn convert_to_dib(input_stream: IStream, use_v5: bool) -> windows::core::Result<Vec<u8>> {
    let factory: IWICImagingFactory = create_instance(&CLSID_WICImagingFactory)?;
    unsafe {
        let decoder =
            factory.CreateDecoderFromStream(&input_stream, null_mut(), Default::default())?;
        let encoder = factory.CreateEncoder(&GUID_ContainerFormatBmp, null_mut())?;
        let output_stream = CreateStreamOnHGlobal(HGLOBAL::default(), true)?;
        encoder.Initialize(&output_stream, WICBitmapEncoderNoCache)?;
        let frame = decoder.GetFrame(0)?;
        let mut encoder_frame = Option::<IWICBitmapFrameEncode>::None;
        let mut property_bag = Option::<IPropertyBag2>::None;
        encoder.CreateNewFrame(&mut encoder_frame as *mut _, &mut property_bag as *mut _)?;
        if let Some(property_bag) = property_bag.as_mut() {
            if use_v5 {
                let mut option = PROPBAG2::default();
                let mut name: Vec<_> = "EnableV5Header32bppBGRA".encode_utf16().collect();
                name.push(0);
                option.pstrName = PWSTR(name.as_ptr() as *mut _);
                let mut variant = VariantInit();
                let inside = &mut variant.Anonymous.Anonymous;
                inside.vt = VT_BOOL;
                inside.Anonymous.boolVal = VARIANT_BOOL(0xFFFFu16 as i16);
                property_bag.Write(1, &mut option as *mut _, &mut variant as *mut _)?;
            }
        }
        let encoder_frame = encoder_frame.unwrap();
        encoder_frame.Initialize(&property_bag.unwrap())?;
        encoder_frame.WriteSource(&frame, std::ptr::null_mut())?;
        encoder_frame.Commit()?;
        encoder.Commit()?;
        let hglobal = GetHGlobalFromStream(&output_stream)?;
        let size = GlobalSize(hglobal);
        let data = GlobalLock(hglobal);
        let v = slice::from_raw_parts(data as *const u8, size);
        // Strip BMP file header
        let sub = &v[14..];
        let res: Vec<u8> = sub.into();
        GlobalUnlock(hglobal).ok();
        // prevent clippy from complaining. want the stream to outlive
        // hglobal
        let _output_stream = output_stream;
        Ok(res)
    }
}

use std::{
    cell::{Cell, RefCell},
    collections::HashMap,
    rc::{Rc, Weak},
    time::Duration,
};

use irondash_message_channel::Late;
use irondash_run_loop::{platform::MessageListener, RunLoop};
use windows::Win32::{
    Foundation::HWND,
    UI::{
        Input::KeyboardAndMouse::{
            GetAsyncKeyState, MapVirtualKeyW, RegisterHotKey, UnregisterHotKey, HOT_KEY_MODIFIERS,
            MAPVK_VSC_TO_VK, MOD_ALT, MOD_CONTROL, MOD_NOREPEAT, MOD_SHIFT, MOD_WIN,
        },
        WindowsAndMessaging::WM_HOTKEY,
    },
};

use crate::{
    error::NativeExtensionsResult,
    hot_key_manager::{HotKeyCreateRequest, HotKeyHandle, HotKeyManagerDelegate},
};

pub struct PlatformHotKeyManager {
    delegate: Weak<dyn HotKeyManagerDelegate>,
    next_id: Cell<i32>,
    hot_keys: RefCell<HashMap<i32, (HotKeyHandle, HotKeyCreateRequest)>>,
    weak_self: Late<Weak<Self>>,
}

impl PlatformHotKeyManager {
    pub fn new(delegate: Weak<dyn HotKeyManagerDelegate>) -> Self {
        Self {
            delegate,
            next_id: Cell::new(65536),
            hot_keys: RefCell::new(HashMap::new()),
            weak_self: Late::new(),
        }
    }

    pub fn assign_weak_self(&self, weak: Weak<PlatformHotKeyManager>) {
        self.weak_self.set(weak.clone());
        RunLoop::current()
            .platform_run_loop
            .register_message_listener(weak);
    }

    fn hwnd() -> HWND {
        HWND(RunLoop::current().platform_run_loop.hwnd())
    }

    pub fn create_hot_key(
        &self,
        handle: HotKeyHandle,
        request: HotKeyCreateRequest,
    ) -> NativeExtensionsResult<()> {
        let mut modifiers = HOT_KEY_MODIFIERS::default();
        if request.alt {
            modifiers |= MOD_ALT;
        }
        if request.control {
            modifiers |= MOD_CONTROL;
        }
        if request.shift {
            modifiers |= MOD_SHIFT;
        }
        if request.meta {
            modifiers |= MOD_WIN;
        }
        modifiers |= MOD_NOREPEAT;
        let id = self.next_id.get();
        self.next_id.replace(id + 1);
        unsafe {
            let vk = MapVirtualKeyW(request.platform_code as u32, MAPVK_VSC_TO_VK);
            RegisterHotKey(Self::hwnd(), id, modifiers, vk)?;
        }
        self.hot_keys.borrow_mut().insert(id, (handle, request));
        Ok(())
    }

    pub fn destroy_hot_key(&self, handle: HotKeyHandle) -> NativeExtensionsResult<()> {
        let mut hot_keys = self.hot_keys.borrow_mut();

        let hot_key_id = hot_keys
            .iter()
            .find(|(_, (h, _))| h == &handle)
            .map(|e| *e.0);
        if let Some(hot_key_id) = hot_key_id {
            hot_keys.remove(&hot_key_id);
            unsafe { UnregisterHotKey(Self::hwnd(), hot_key_id)? };
        }

        Ok(())
    }

    fn wait_until_release(
        request: HotKeyCreateRequest,
        handle: HotKeyHandle,
        delegate: Rc<dyn HotKeyManagerDelegate>,
    ) {
        let vk = unsafe { MapVirtualKeyW(request.platform_code as u32, MAPVK_VSC_TO_VK) };
        let key_state = unsafe { GetAsyncKeyState(vk as i32) };
        if key_state < 0 {
            RunLoop::current()
                .schedule(Duration::from_millis(10), move || {
                    Self::wait_until_release(request, handle, delegate);
                })
                .detach();
        } else {
            delegate.on_hot_key_released(handle);
        }
    }

    fn on_hot_key(&self, hot_key: i32) {
        let hot_key = self.hot_keys.borrow().get(&hot_key).cloned();
        let delegate = self.delegate.upgrade();
        if let (Some((handle, request)), Some(delegate)) = (hot_key, delegate) {
            delegate.on_hot_key_pressed(handle);
            Self::wait_until_release(request, handle, delegate);
        }
    }
}

impl Drop for PlatformHotKeyManager {
    fn drop(&mut self) {
        let message_listener: Weak<dyn MessageListener> = self.weak_self.clone();
        if let Ok(run_loop) = RunLoop::try_current() {
            run_loop
                .platform_run_loop
                .unregister_message_listener(&message_listener);
        }
    }
}

impl MessageListener for PlatformHotKeyManager {
    fn on_window_message(&self, _hwnd: isize, message: u32, w_param: usize, _l_param: isize) {
        if message == WM_HOTKEY {
            self.on_hot_key(w_param as _)
        }
    }
}

