    provider: Rc<PlatformDataProvider>,
    _handle: Arc<DataProviderHandle>,
}

pub struct DataObject {
    providers: Vec<ProviderEntry>,
    cache: RefCell<HashMap<DataProviderValueId, Option<Vec<u8>>>>,
}

impl DataObject {
    pub fn new(providers: Vec<(Rc<PlatformDataProvider>, Arc<DataProviderHandle>)>) -> Rc<Self> {
        Rc::new(Self {
            providers: providers
                .into_iter()
                .map(|p| ProviderEntry {
                    provider: p.0,
                    _handle: p.1,
                })
                .collect(),
            cache: RefCell::new(HashMap::new()),
        })
    }

    fn set_data_(selection_data: &SelectionData, data: &[u8]) -> NativeExtensionsResult<()> {
        let target = selection_data.target();
        if target_includes_text(&target) {
            selection_data.set_text(
                std::str::from_utf8(data)
                    .map_err(|e| NativeExtensionsError::OtherError(e.to_string()))?,
            );
        } else {
            selection_data.set(&target, 8, data);
        }
        Ok(())
    }

    fn get_data_for_item(&self, item: &PlatformDataProvider, ty: &str) -> Option<Vec<u8>> {
        for data in &item.data.representations {
            match data {
                DataRepresentation::Simple { format, data } => {
                    if format == ty {
                        return data.coerce_to_data(StringFormat::Utf8);
                    }
                }
                DataRepresentation::Lazy { format, id } => {
                    if format == ty {
                        if let Some(cached) = self.cache.borrow().get(id).cloned() {
                            return cached;
                        }
                        if let Some(delegate) = item.delegate.upgrade() {
                            let promise = delegate.get_lazy_data(item.isolate_id, *id, None);
                            loop {
                                if let Some(result) = promise.try_take() {
                                    match result {
                                        crate::value_promise::ValuePromiseResult::Ok { value } => {
                                            let data = value.coerce_to_data(StringFormat::Utf8);
                                            self.cache.borrow_mut().insert(*id, data.clone());
                                            return data;
                                        }
                                        crate::value_promise::ValuePromiseResult::Cancelled => {
                                            return None;
                                        }
                                    }
                                }
                                RunLoop::current().platform_run_loop.poll_once();
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        None
    }

    pub fn get_data(&self, selection_data: &SelectionData) -> NativeExtensionsResult<()> {
        let target = selection_data.target();
        let is_text = target_includes_text(&target);

        let target = if is_text {
            TYPE_TEXT.to_owned()
        } else {
            target.name().as_str().to_owned()
        };
        if target == TYPE_URI {
            // merge URIs from all items
            let mut data = Vec::<u8>::new();
            for item in &self.providers {
                if let Some(item_data) = self.get_data_for_item(&item.provider, &target) {
                    data.extend_from_slice(&item_data);
                    data.push(b'\r');
                    data.push(b'\n');
                }
            }
            Self::set_data_(selection_data, &data)?;
        } else if let Some(item) = self.providers.first() {
            if let Some(data) = self.get_data_for_item(&item.provider, &target) {
                Self::set_data_(selection_data, &data)?;
            }
        }
        Ok(())
    }

    pub fn write_to_clipboard(self: &Rc<Self>) -> NativeExtensionsResult<()> {
        unsafe { gtk::set_initialized() };
        let list = self.create_target_list();
        let targets = list.get_target_entries();
        let display = Display::default()
            .ok_or_else(|| NativeExtensionsError::OtherError("Display not found".into()))?;
        let clipboard = Clipboard::default(&display)
            .ok_or_else(|| NativeExtensionsError::OtherError("Clipboard not found".into()))?;
        let self_clone = self.clone();
        clipboard.set_with_data(&targets, move |_, selection_data, _| {
            self_clone.get_data(selection_data).ok_log();
        });
        Ok(())
    }

    pub fn create_target_list(&self) -> TargetList {
        let list = TargetList::new(&[]);
        fn add(list: &TargetList, ty: &str) {
            if ty == TYPE_TEXT {
                list.add_text_targets(0);
            } else {
                list.add(&Atom::intern(ty), 0, 0);
            }
        }
        if let Some(item) = self.providers.first() {
            for repr in &item.provider.data.representations {
                match repr {
                    DataRepresentation::Simple { format, data: _ } => {
                        add(&list, format);
                    }
                    DataRepresentation::Lazy { format, id: _ } => {
                        add(&list, format);
                    }
                    _ => {}
                }
            }
        }
        list
    }
}

use std::ffi::{CStr, CString};

use gdk::{
    cairo::{Format, ImageSurface},
    glib::translate::{FromGlibPtrNone, ToGlibPtr, ToGlibPtrMut},
    Atom, Event, EventType,
};
use gdk_sys::{gdk_atom_intern, gdk_atom_name, GdkAtom};
use glib_sys::GFALSE;
use gtk::{TargetEntry, TargetList};
use gtk_sys::{gtk_target_table_new_from_list, gtk_targets_include_text};

use crate::api_model::ImageData;
use crate::error::{NativeExtensionsError::OtherError, NativeExtensionsResult};

// Use gtk function to set/retrieve text (there are multiple possible format,
// we don't want to mess with that)
pub const TYPE_TEXT: &str = "text/plain";

// Special care for URIs. When writing URIs from multiple items are merged into one
// URI list, when reading URI list is split into multiple items.
pub const TYPE_URI: &str = "text/uri-list";

pub trait AtomExt {
    fn from_string(s: &str) -> GdkAtom;
    fn to_string(&self) -> String;
}

impl AtomExt for GdkAtom {
    fn from_string(s: &str) -> GdkAtom {
        let s = CString::new(s).unwrap();
        unsafe { gdk_atom_intern(s.as_ptr(), GFALSE) }
    }

    fn to_string(&self) -> String {
        unsafe {
            let s = gdk_atom_name(*self);
            CStr::from_ptr(s).to_string_lossy().into()
        }
    }
}

pub fn target_includes_text(target: &Atom) -> bool {
    let res = unsafe { gtk_targets_include_text(&mut target.to_glib_none().0, 1) };
    res != GFALSE
}

pub trait TargetListExt {
    fn get_target_entries(&self) -> Vec<TargetEntry>;
}

impl TargetListExt for TargetList {
    fn get_target_entries(&self) -> Vec<TargetEntry> {
        let mut n_targets = 0;
        let targets =
            unsafe { gtk_target_table_new_from_list(self.to_glib_none().0, &mut n_targets) };
        let mut entries = Vec::<TargetEntry>::new();
        for i in 0..n_targets as usize {
            entries.push(unsafe { TargetEntry::from_glib_none(targets.add(i)) })
        }
        entries
    }
}

pub fn surface_from_image_data(image: ImageData, opacity: f64) -> ImageSurface {
    let factor: i32 = (opacity * 255.0) as i32;

    let mut data = image.data;
    for offset in (0..data.len()).step_by(4) {
        let (r, g, b, a) = (
            data[offset],
            data[offset + 1],
            data[offset + 2],
            data[offset + 3],
        );

        let a = if factor == 255 {
            a
        } else {
            (a as i32 * factor / 255) as u8
        };

        // Premultiply alpha
        data[offset] = (b as i32 * a as i32 / 255) as u8;
        data[offset + 1] = (g as i32 * a as i32 / 255) as u8;
        data[offset + 2] = (r as i32 * a as i32 / 255) as u8;
        data[offset + 3] = a;
    }
    let surface = ImageSurface::create_for_data(
        data,
        Format::ARgb32,
        image.width,
        image.height,
        image.bytes_per_row,
    );
    let res = surface.unwrap();
    res.set_device_scale(
        image.device_pixel_ratio.unwrap_or(1.0),
        image.device_pixel_ratio.unwrap_or(1.0),
    );
    res
}

pub(super) fn synthesize_button_up(event: &Event) -> NativeExtensionsResult<Event> {
    if event.event_type() != EventType::ButtonPress
        && event.event_type() != EventType::DoubleButtonPress
        && event.event_type() != EventType::TripleButtonPress
    {
        return Err(OtherError(format!(
            "invalid button event: {}",
            event.event_type()
        )));
    }
    let mut event = event.clone();
    let e: *mut gdk_sys::GdkEvent = event.to_glib_none_mut().0;
    let e = unsafe { &mut *e };
    e.type_ = gdk_sys::GDK_BUTTON_RELEASE;
    Ok(event)
}

