pub fn uri_from_string<'a>(env: &mut JNIEnv<'a>, string: &str) -> JniResult<JObject<'a>> {
    let string = env.new_string(string)?;
    env.call_static_method(
        "android/net/Uri",
        "parse",
        "(Ljava/lang/String;)Landroid/net/Uri;",
        &[(&string).into()],
    )?
    .l()
}

