import 'dart:ui' as ui;
import 'package:flutter/foundation.dart';
import 'package:flutter/rendering.dart';

import '../util.dart';

/// Represents a snapshot of widget.
class WidgetSnapshot {
  /// Creates a new widget snapshot backed by ui.Image.
  /// This is used on platforms that can rasterize widgets to images
  /// (Native + CanvasKit).
  WidgetSnapshot.image(this._image)
      : _renderObject = null,
        _renderObjectBounds = null;

  /// Creates a new widget snapshot backed by a render object.
  /// [bounds] represents the part of the render object that should be
  /// visible.
  WidgetSnapshot.renderObject(this._renderObject, Rect bounds)
      : _image = null,
        _renderObjectBounds = bounds;

  /// Key used to create this snapshot.
  Object? debugKey;

  /// Returns whether this is image backed widget snapshot.
  bool get isImage {
    assert(!_disposed);
    return _image != null;
  }

  /// Returns image representation of this snapshot.
  ui.Image get image {
    assert(!_disposed);
    assert(isImage);
    return _image!;
  }

  /// Returns whether this is render object backed widget snapshot.
  bool get isRenderObject {
    assert(!_disposed);
    return _renderObject != null;
  }

  int _retainCount = 1;

  /// Increases the retain count of this snapshot. This allows using snapshot
  /// in multiple places (i.e. lift & drag having same image).
  WidgetSnapshot retain() {
    _retainCount++;
    return this;
  }

  /// Returns render object representation of this snapshot. Note that this
  /// can only be called per snapshot. After that the render object is free to be disposed.
  /// If you need to use snapshot in multiple places (i.e. lift & drag having same image)
  /// use [retain] to increase the retain count.
  RenderObject? getRenderObject() {
    assert(!_disposed);
    assert(_retainCount > 0);
    --_retainCount;

    if (_retainCount == 0) {
      _onRenderObjectRequested.notify();
    }
    if (_retainCount >= 0) {
      return _renderObject!;
    } else {
      return null;
    }
  }

  bool get debugRenderObjectRequested => _retainCount <= 0;

  /// Returns part of the render object represented by this snapshot.
  Rect get renderObjectBounds {
    assert(!_disposed);
    assert(isRenderObject);
    return _renderObjectBounds!;
  }

  double get pointWidth => pointSize.width;
  double get pointHeight => pointSize.height;

  Listenable get onDisposed => _onDisposed;
  Listenable get onRenderObjectRequested => _onRenderObjectRequested;

  final _onDisposed = SimpleNotifier();
  final _onRenderObjectRequested = SimpleNotifier();

  bool _disposed = false;

  void dispose() {
    assert(!_disposed);
    _onDisposed.notify();
    _onDisposed.dispose();
    _image?.dispose();
    _disposed = true;
  }

  Size get pointSize {
    if (isImage) {
      return Size(
        _image!.width / (_image.devicePixelRatio ?? 1.0),
        _image.height / (_image.devicePixelRatio ?? 1.0),
      );
    } else {
      return _renderObjectBounds!.size;
    }
  }

  @override
  String toString() {
    return 'WidgetSnapshot ${_image != null ? 'image' : 'renderObject'} ${identityHashCode(this)} (Debug Key: $debugKey)';
  }

  final ui.Image? _image;
  final RenderObject? _renderObject;
  final Rect? _renderObjectBounds;
}

/// Image representation of part of user interface.
class TargetedWidgetSnapshot {
  TargetedWidgetSnapshot(this.snapshot, this.rect);

  /// Image to be used as avatar image.
  final WidgetSnapshot snapshot;

  /// Initial position of avatar image (in global coordinates).
  final Rect rect;

  /// Retains the targeted snapshot. See [WidgetSnapshot.retain].
  TargetedWidgetSnapshot retain() {
    snapshot.retain();
    return this;
  }

  void dispose() {
    snapshot.dispose();
  }
}

final _devicePixelRatio = Expando('devicePixelRatio');

/// Extension on image that allows to store device pixel ratio alongside the
/// image itself.
extension DevicePixelRatio on ui.Image {
  /// Device pixel ratio of the image or null if not set.
  double? get devicePixelRatio => _devicePixelRatio[this] as double?;

  set devicePixelRatio(double? value) {
    _devicePixelRatio[this] = value;
  }

  /// Returns the width of image in resolution independent points.
  double get pointWidth => width / (devicePixelRatio ?? 1.0);

  /// Returns the height of image in resolution independent points.
  double get pointHeight => height / (devicePixelRatio ?? 1.0);

  ui.Size get pointSize {
    final devicePixelRatio = this.devicePixelRatio ?? 1.0;
    return ui.Size(width / devicePixelRatio, height / devicePixelRatio);
  }
}

import 'package:flutter/rendering.dart';
import 'package:flutter/widgets.dart';

import 'widget_snapshot.dart';

class DisplayWidgetSnapshot extends StatelessWidget {
  final WidgetSnapshot snapshot;

  const DisplayWidgetSnapshot(
    this.snapshot, {
    super.key,
  });

  @override
  Widget build(BuildContext context) {
    if (snapshot.isImage) {
      return RawImage(
        image: snapshot.image,
        fit: BoxFit.fill,
      );
    } else {
      return LayoutBuilder(builder: (context, constraints) {
        return Transform.scale(
          alignment: Alignment.topLeft,
          scaleX: constraints.biggest.width / snapshot.pointSize.width,
          scaleY: constraints.biggest.height / snapshot.pointSize.height,
          child: _WidgetSnapshotWidget(snapshot),
        );
      });
    }
  }
}

class _WidgetSnapshotWidget extends SingleChildRenderObjectWidget {
  _WidgetSnapshotWidget(
    this.snapshot,
  ) : assert(snapshot.isRenderObject);

  final WidgetSnapshot snapshot;

  @override
  RenderObject createRenderObject(BuildContext context) {
    assert(!snapshot.debugRenderObjectRequested);
    return _RenderWidgetSnapshot()..snapshot = snapshot;
  }

  @override
  void updateRenderObject(
      BuildContext context, covariant RenderObject renderObject) {
    final renderObject_ = renderObject as _RenderWidgetSnapshot;
    if (renderObject_.snapshot != snapshot) {
      assert(!snapshot.debugRenderObjectRequested);
      renderObject_.snapshot = snapshot;
      renderObject_.didPaint = false;
    }
  }
}

class _RenderWidgetSnapshot extends RenderProxyBox {
  WidgetSnapshot? snapshot;

  @override
  bool get isRepaintBoundary => true;

  @override
  void performLayout() {
    size = constraints.biggest;
  }

  @override
  void markNeedsPaint() {
    if (!didPaint) {
      super.markNeedsPaint();
    }
  }

  bool didPaint = false;

  @override
  void paint(PaintingContext context, Offset offset) {
    final snapshot = this.snapshot;
    if (snapshot != null) {
      final renderObject = snapshot.getRenderObject();
      renderObject?.paint(
        context,
        offset - snapshot.renderObjectBounds.topLeft,
      );
    }
    didPaint = true;
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

import '../reader.dart';
import '../reader_manager.dart';

/// Unlike native implementation, item handle on web contains the actual implementation and
/// [ReaderManagerImpl] merely forwards calls to the handle.
abstract class $DataReaderItemHandle {
  Future<List<String>> getFormats();
  Future<Object?> getDataForFormat(String format);
  Future<String?> suggestedName();
  Future<bool> canGetVirtualFile(String format);
  Future<VirtualFileReceiver?> createVirtualFileReceiver(
    DataReaderItemHandle handle, {
    required String format,
  });
}

class SimpleProgress extends ReadProgress {
  @override
  void cancel() {}

  @override
  ValueListenable<bool> get cancellable => _cancellable;

  @override
  ValueListenable<double?> get fraction => _fraction;

  void done() {
    _fraction.value = 1.0;
  }

  final _cancellable = ValueNotifier(false);
  final _fraction = ValueNotifier<double?>(null);
}

class $DataReaderHandle {
  $DataReaderHandle(this.items);
  final List<$DataReaderItemHandle> items;
}

/// ReaderManagerImpl on web forwards calls to underlying handles.
class ReaderManagerImpl extends ReaderManager {
  @override
  Future<void> dispose(DataReaderHandle reader) async {
    // We don't register the items anywhere so there's nothing to unregister.
  }

  @override
  (Future<Object?>, ReadProgress) getItemData(
    DataReaderItemHandle handle, {
    required String format,
  }) {
    final impl = handle as $DataReaderItemHandle;
    final progress = SimpleProgress();
    final res = impl.getDataForFormat(format);
    final completer = Completer<Object?>();
    res.then((value) {
      progress.done();
      completer.complete(value);
    }).catchError((error) {
      progress.done();
      completer.completeError(error);
    });
    return (completer.future, progress);
  }

  @override
  Future<List<String>> getItemFormats(DataReaderItemHandle handle) {
    final impl = handle as $DataReaderItemHandle;
    return impl.getFormats();
  }

  @override
  Future<List<DataReaderItemHandle>> getItems(DataReaderHandle reader) async {
    final handle = reader as $DataReaderHandle;
    return handle.items.map((e) => e as DataReaderItemHandle).toList();
  }

  @override
  Future<List<DataReaderItemInfo>> getItemInfo(
    Iterable<DataReaderItemHandle> handles, {
    Duration? timeout,
  }) async {
    final res = <DataReaderItemInfo>[];
    final stopwatch = Stopwatch()..start();
    for (final handle in handles) {
      final impl = handle as $DataReaderItemHandle;
      final formats = await impl.getFormats();
      final receivers = <VirtualFileReceiver>[];
      for (final format in formats) {
        if (await impl.canGetVirtualFile(format)) {
          final receiver =
              await impl.createVirtualFileReceiver(handle, format: format);
          if (receiver != null) {
            receivers.add(receiver);
          }
        }
      }
      final info = DataReaderItemInfo(
        handle,
        formats: formats,
        synthesizedFormats: [],
        virtualReceivers: receivers,
        suggestedName: await impl.suggestedName(),
        synthesizedFromURIFormat: null,
      );
      res.add(info);
      if (timeout != null && stopwatch.elapsed > timeout) {
        break;
      }
    }
    return res;
  }

  @override
  VirtualFile createVirtualFileFromUri(Uri uri) {
    throw UnsupportedError('createVirtualFileFromUri is not supported on web');
  }
}

