abstract class DragOverlayState<T extends StatefulWidget> extends State<T> {
  void updatePosition(Offset position);
  void animateHome(Duration duration, VoidCallback onCompleted);
}

class DragOverlayDesktop extends StatefulWidget {
  final List<TargetedWidgetSnapshot> snapshots;
  final Offset initialPosition;

  const DragOverlayDesktop({
    super.key,
    required this.snapshots,
    required this.initialPosition,
  });

  @override
  State<StatefulWidget> createState() => _DragOverlayDesktopState();
}

class _DragOverlayDesktopState extends DragOverlayState<DragOverlayDesktop> {
  Offset _position = Offset.zero;

  @override
  void initState() {
    super.initState();
    _position = widget.initialPosition;
  }

  @override
  void animateHome(Duration duration, VoidCallback onCompleted) {
    _homeAnimation = SimpleAnimation.animate(duration, (value) {
      setState(() {
        _homeTransition = value;
      });
    }, onEnd: onCompleted);
  }

  SimpleAnimation? _homeAnimation;

  double? _homeTransition;

  @override
  void dispose() {
    super.dispose();
    _homeAnimation?.cancel();
  }

  @override
  void updatePosition(Offset position) {
    setState(() {
      _position = position;
    });
  }

  @override
  Widget build(BuildContext context) {
    var delta = _position - widget.initialPosition;
    if (_homeTransition != null) {
      delta = Offset.lerp(
        delta,
        Offset.zero,
        Curves.easeOutCubic.transform(_homeTransition!),
      )!;
    }

    final renderObject = context.findAncestorRenderObjectOfType<RenderBox>()!;

    double opacity = 0.7 * (1.0 - (_homeTransition ?? 0.0));

    return IgnorePointer(
      ignoring: true,
      child: Stack(
        fit: StackFit.expand,
        children: [
          for (var snapshot in widget.snapshots)
            () {
              final local = renderObject.globalToLocal(snapshot.rect.topLeft);
              return Positioned(
                left: local.dx + delta.dx,
                top: local.dy + delta.dy,
                width: snapshot.snapshot.pointWidth,
                height: snapshot.snapshot.pointHeight,
                child: Opacity(
                  opacity: opacity,
                  child: ShadowImage(
                    image: snapshot.snapshot,
                    shadowRadius: kShadowRadius,
                    shadowOpacity: 1.0,
                  ),
                ),
              );
            }()
        ],
      ),
    );
  }
}

class DragOverlayMobile extends StatefulWidget {
  const DragOverlayMobile({
    required this.snapshot,
    required this.initialPosition,
    Key? key,
  }) : super(key: key);

  final TargetedWidgetSnapshot snapshot;
  final Offset initialPosition;

  @override
  State<StatefulWidget> createState() => _DragOverlayMobileState();
}

class _DragOverlayMobileState extends DragOverlayState<DragOverlayMobile> {
  Offset _position = Offset.zero;

  @override
  void initState() {
    super.initState();
    _position = widget.initialPosition;
  }

  @override
  void updatePosition(Offset position) {
    setState(() {
      _position = position;
    });
  }

  double? _homeTransition;

  @override
  Widget build(BuildContext context) {
    var offset = Offset(
        _position.dx - widget.snapshot.snapshot.pointWidth / 2.0,
        _position.dy - widget.snapshot.snapshot.pointHeight / 2.0);

    if (_homeTransition != null) {
      offset = Offset.lerp(
        offset,
        widget.snapshot.rect.topLeft,
        Curves.easeOutCubic.transform(_homeTransition!),
      )!;
    }

    final renderObject = context.findAncestorRenderObjectOfType<RenderBox>()!;
    offset = renderObject.globalToLocal(offset);

    double opacity = 0.7 * (1.0 - (_homeTransition ?? 0.0));

    return IgnorePointer(
      ignoring: true,
      child: Stack(
        children: [
          Positioned(
            left: offset.dx,
            top: offset.dy,
            width: widget.snapshot.snapshot.pointWidth,
            height: widget.snapshot.snapshot.pointHeight,
            child: Opacity(
              opacity: opacity,
              child: DisplayWidgetSnapshot(widget.snapshot.snapshot),
            ),
          ),
        ],
      ),
    );
  }

  SimpleAnimation? _homeAnimation;

  @override
  void dispose() {
    super.dispose();
    _homeAnimation?.cancel();
  }

  @override
  void animateHome(Duration duration, VoidCallback onCompleted) {
    _homeAnimation = SimpleAnimation.animate(duration, (value) {
      setState(() {
        _homeTransition = value;
      });
    }, onEnd: onCompleted);
  }
}

import 'dart:js_interop';
import 'dart:ui' as ui;

import 'package:flutter/gestures.dart';
import 'package:web/web.dart' as web;

abstract class DragDriverDelegate {
  void cancel();
  void update(ui.Offset position);
  void end(ui.Offset position);
}

class DragDriver {
  DragDriver({
    required this.pointer,
    required this.delegate,
    required this.devicePixelRatio,
  }) {
    web.document.addEventListener(
      'keydown',
      _keyDown = _onKeyDown.toJS,
      true.toJS,
    );
    // During drag all pointer events to Flutter need to be postponed
    // in order to be consistent with how drag&drop works on desktop platforms.
    // Flutter web registers mouse move listener on dom window. Since
    // there is no way to override listener itself, we override the
    // onPointerDataPacket callback instead.
    _previousPointerDataPacketCallback =
        ui.PlatformDispatcher.instance.onPointerDataPacket;
    ui.PlatformDispatcher.instance.onPointerDataPacket = _onPointerDataPacket;
  }

  final double devicePixelRatio;
  final int pointer;
  late ui.PointerDataPacketCallback? _previousPointerDataPacketCallback;
  late web.EventListener _keyDown;

  void _onKeyDown(JSObject event) {
    final keyEvent = event as web.KeyboardEvent;
    if (keyEvent.key.toLowerCase() == 'escape') {
      cancel();
    }
  }

  void _cleanup() {
    web.document.removeEventListener('keydown', _keyDown, true.toJS);
    ui.PlatformDispatcher.instance.onPointerDataPacket =
        _previousPointerDataPacketCallback;
  }

  bool _didReleasePointer = false;

  void _onPointerDataPacket(ui.PointerDataPacket packet) {
    for (final data in packet.data) {
      _onPointerDataPacketInner(ui.PointerDataPacket(data: [data]));
    }
  }

  void _onPointerDataPacketInner(ui.PointerDataPacket packet) {
    // If this is not our packet pass it through.
    if (packet.data.any((element) =>
        element.pointerIdentifier != pointer ||
        element.signalKind == ui.PointerSignalKind.scroll)) {
      _previousPointerDataPacketCallback?.call(packet);
      return;
    }
    final data = packet.data.first;
    if (!_didReleasePointer) {
      if (data.change == ui.PointerChange.move) {
        // Synthesize pointer up event to pass to framework.
        _didReleasePointer = true;
        final newData = ui.PointerData(
          buttons: 0,
          pointerIdentifier: data.pointerIdentifier,
          device: data.device,
          change: ui.PointerChange.cancel,
          kind: data.kind,
          timeStamp: data.timeStamp,
          physicalX: data.physicalX,
          physicalY: data.physicalY,
          synthesized: true,
        );
        _previousPointerDataPacketCallback
            ?.call(ui.PointerDataPacket(data: [newData]));
      } else if (data.change == ui.PointerChange.up) {
        // This data already is pointer up event. There was no move.
        _previousPointerDataPacketCallback?.call(packet);
      }
      _didReleasePointer = true;
    }
    final offset = ui.Offset(
        data.physicalX / devicePixelRatio, data.physicalY / devicePixelRatio);
    delegate.update(offset);
    if (data.change == ui.PointerChange.up ||
        data.change == ui.PointerChange.cancel ||
        data.change == ui.PointerChange.remove) {
      delegate.end(offset);
      // Synthesize hover packet to properly update mouse regions.
      if (data.kind == PointerDeviceKind.mouse) {
        final newData = ui.PointerData(
          buttons: 0,
          device: data.device,
          pointerIdentifier: data.pointerIdentifier,
          change: ui.PointerChange.hover,
          kind: data.kind,
          timeStamp: data.timeStamp,
          physicalX: data.physicalX,
          physicalY: data.physicalY,
          synthesized: true,
        );
        _previousPointerDataPacketCallback
            ?.call(ui.PointerDataPacket(data: [newData]));
      }
      _cleanup();
    }
  }

  void cancel() {
    _cleanup();
    delegate.cancel();
  }

  final DragDriverDelegate delegate;
}

