/// 1 Channel Stack Blur Algorithm.
void blurImageData(
    Uint8List pixels, int topX, int topY, int width, int height, int radius) {
  final div = 2 * radius + 1;
  final widthMinus1 = width - 1;
  final heightMinus1 = height - 1;
  final radiusPlus1 = radius + 1;
  final sumFactor = radiusPlus1 * (radiusPlus1 + 1) ~/ 2;

  final stack = Uint8List(div);

  const stackStart = 0;
  final stackEnd = radiusPlus1;

  int stackIn = 0;
  int stackOut = 0;

  @tryInline
  void nextStackIn() {
    stackIn = (stackIn + 1) % stack.length;
  }

  @tryInline
  void nextStackOut() {
    stackOut = (stackOut + 1) % stack.length;
  }

  final mulSum = _mulTable[radius];
  final shgSum = _shgTable[radius];

  int p;
  int yw = 0, yi = 0;

  for (var y = 0; y < height; y++) {
    var pr = pixels[yi];
    var rOutSum = radiusPlus1 * pr;
    var rSum = sumFactor * pr;

    for (var i = 0; i < radiusPlus1; i++) {
      stack[i] = pr;
    }

    var rInSum = 0;
    for (var i = 1; i < radiusPlus1; i++) {
      p = yi + ((widthMinus1 < i ? widthMinus1 : i));
      rSum +=
          (stack[i - 1 + radiusPlus1] = (pr = pixels[p])) * (radiusPlus1 - i);
      rInSum += pr;
    }

    stackIn = stackStart;
    stackOut = stackEnd;
    for (var x = 0; x < width; x++) {
      pixels[yi] = (rSum * mulSum) >> shgSum;
      rSum -= rOutSum;
      rOutSum -= stack[stackIn];
      p = (yw + ((p = x + radius + 1) < widthMinus1 ? p : widthMinus1));
      rInSum += (stack[stackIn] = pixels[p]);
      rSum += rInSum;
      nextStackIn();
      rOutSum += (pr = stack[stackOut]);
      rInSum -= pr;
      nextStackOut();
      yi += 1;
    }
    yw += width;
  }

  for (var x = 0; x < width; x++) {
    yi = x;
    var pr = pixels[yi];
    var rOutSum = radiusPlus1 * pr;
    var rSum = sumFactor * pr;

    for (var i = 0; i < radiusPlus1; i++) {
      stack[i] = pr;
    }

    var rInSum = 0;
    for (var i = 1, yp = width; i <= radius; i++) {
      yi = (yp + x);
      rSum +=
          (stack[i - 1 + radiusPlus1] = (pr = pixels[yi])) * (radiusPlus1 - i);
      rInSum += pr;
      if (i < heightMinus1) {
        yp += width;
      }
    }

    yi = x;
    stackIn = stackStart;
    stackOut = stackEnd;
    for (var y = 0; y < height; y++) {
      p = yi;
      pixels[p] = (rSum * mulSum) >> shgSum;
      rSum -= rOutSum;
      rOutSum -= stack[stackIn];
      p = (x +
          (((p = y + radiusPlus1) < heightMinus1 ? p : heightMinus1) * width));
      rSum += (rInSum += (stack[stackIn] = pixels[p]));
      nextStackIn();
      rOutSum += (pr = stack[stackOut]);
      rInSum -= pr;
      nextStackOut();
      yi += width;
    }
  }
}

