double _easeOut(double value) {
  const curve = Cubic(0.1, 0.48, 0.31, 0.57);
  return curve.transform(value);
}

const kShadowRadius = 12;

class OverlayWidgetState extends State<OverlayWidget>
    implements MobileMenuDelegate {
  @override
  void initState() {
    super.initState();
    for (final _ in widget.configuration.secondaryItems) {
      _secondaryDragKeys.add(GlobalKey());
      _secondaryLiftKeys.add(GlobalKey());
      _secondaryRenderKeys.add(GlobalKey());
    }
  }

  @override
  void dispose() {
    _menuCanScrollNotifier.dispose();
    _resetMenuOffsetAnimation?.cancel();
    _menuDragOffsetAnimation?.cancel();
    _hidingAnimation?.cancel();
    _onDisposed.notify();
    _onDisposed.dispose();
    super.dispose();
  }

  double _menuDragExtent = 0;

  double get menuDragExtent => _menuDragExtent;

  void setMenuDragExtent(double value) {
    _menuDragExtent = value;
  }

  double get menuDragOffset => _currentState.menuDragOffset;

  final _repaintBoundary = GlobalKey();

  WidgetSnapshot getSnapshot() {
    final boundary = _repaintBoundary.currentContext!.findRenderObject()
        as RenderBetterRepaintBoundary;
    final pixelRatio = MediaQuery.of(context).devicePixelRatio;
    var size = Size(
      widget.configuration.primaryItem.dragImage.pointWidth + kShadowRadius * 2,
      widget.configuration.primaryItem.dragImage.pointHeight +
          kShadowRadius * 2,
    );
    for (final key in _secondaryRenderKeys) {
      final renderObject = key.currentContext!.findRenderObject();
      if (renderObject != null) {
        final box = renderObject as RenderBox;
        final transform = box.getTransformTo(boundary);
        final rect =
            MatrixUtils.transformRect(transform, box.paintBounds).inflate(14.0);
        size = Size(
          math.max(size.width, rect.width),
          math.max(size.height, rect.height),
        );
      }
    }

    final rect = Rect.fromCenter(
        center: boundary.globalToLocal(_currentState.globalPosition),
        width: size.width,
        height: size.height);

    if (WidgetSnapshotter.snapshotToImageSupported()) {
      final image = boundary.toImageSync(bounds: rect, pixelRatio: pixelRatio)
        ..devicePixelRatio = pixelRatio;
      return WidgetSnapshot.image(image);
    } else {
      return WidgetSnapshot.renderObject(
        boundary,
        rect,
      );
    }
  }

  double _angleForSecondaryItem(int index) {
    final step = 0.2 / (widget.configuration.secondaryItems.length / 2);
    final flip = index % 2 == 0 ? 1 : -1;
    return step *
        flip *
        (widget.configuration.secondaryItems.length - index) /
        2;
  }

  final _menuCanScrollNotifier = ValueNotifier(true);

  AlignmentGeometry _menuAlignment = Alignment.center;

  BoxConstraints? _lastConstraints;

  @override
  Widget build(BuildContext context) {
    if (widget.configuration.menuConfiguration != null) {
      return ValueListenableBuilder<MenuPreviewWidget?>(
        valueListenable: widget.configuration.menuConfiguration!.menuPreview,
        builder: (context, menuPreview, _) {
          return LayoutBuilder(builder: (context, constraints) {
            // Hide menu on rotation. The underlying widgets have likely been rebuilt anyway.
            if (_lastConstraints != null && _lastConstraints != constraints) {
              hide();
            }
            _lastConstraints = constraints;
            return _build(context, menuPreview);
          });
        },
      );
    } else {
      return _build(context, null);
    }
  }

  final _onDisposed = SimpleNotifier();

  final _layoutState = OverlayLayoutState();

  Widget _build(BuildContext context, MenuPreviewWidget? menuPreview) {
    final menuConfiguration = widget.configuration.menuConfiguration;

    final backgroundOpacity = _currentState.menuFactor *
        (1.0 - _currentState.dragFactor) *
        (1.0 - _hideFactor);

    final mediaQuery = MediaQuery.of(context);

    final liftOpacity =
        1.0 - math.max(_currentState.menuFactor, _currentState.dragFactor);

    // Bump the opacity a bit in the middle of transition to avoid background
    // showing through.
    const menuOpacityCurve = Cubic(0.16, 0.7, 0.41, 0.88);
    final menuOpacity = menuOpacityCurve.transform(_currentState.menuFactor) *
        (1.0 - _currentState.dragFactor);

    final dragOpacity = _currentState.dragFactor * 1;

    double secondaryLiftAlpha = (_currentState.dragFactor * 10).clamp(0, 1) *
        (1 - _currentState.dragFactor);
    double secondaryDragAlpha = _currentState.dragFactor;

    final renderBox = context.findAncestorRenderObjectOfType<RenderBox>()!;
    final transform = renderBox.getTransformTo(null)..invert();

    Rect rectToLocal(Rect rect) => MatrixUtils.transformRect(transform, rect);
    Offset pointToLocal(Offset offset) =>
        MatrixUtils.transformPoint(transform, offset);

    final layoutDelegate = OverlayLayoutDelegate(
      layoutState: _layoutState,
      pixelSnap: PixelSnap.of(context),
      padding: mediaQuery.padding,
      menuDragExtentSetter: setMenuDragExtent,
      canScrollMenuSetter: (value) {
        _menuCanScrollNotifier.value = value;
      },
      hasCustomMenuPreview: menuConfiguration?.hasCustomMenuPreview ?? false,
      menuAlignmentSetter: (value) {
        _menuAlignment = value;
      },
      primaryItem: LayoutItemConfiguration(
        index: 0,
        liftChildId: _liftKey,
        dragChildId: _dragKey,
        liftRect: rectToLocal(widget.configuration.primaryItem.liftImage.rect),
        dragSize: widget.configuration.primaryItem.dragImage.pointSize,
        liftImage: widget.configuration.primaryItem.liftImage.snapshot,
        dragImage: widget.configuration.primaryItem.dragImage,
      ),
      menuPreviewSize: menuPreview?.size,
      menuPreviewId: _menuPreviewKey,
      menuId: _menuKey,
      secondaryItems:
          widget.configuration.secondaryItems.mapIndexed((int index, e) {
        return LayoutItemConfiguration(
          index: index,
          liftChildId: _secondaryLiftKeys[index],
          dragChildId: _secondaryDragKeys[index],
          liftRect: rectToLocal(e.liftImage.rect),
          dragSize: e.dragImage.pointSize,
          liftImage: e.liftImage.snapshot,
          dragImage: e.dragImage,
        );
      }).toList(growable: false),
      dragState: _currentState.copyWith(
          globalPosition: pointToLocal(
        _currentState.globalPosition,
      )),
    );

    return MultiTouchDetector(
      child: RawGestureDetector(
        behavior: HitTestBehavior.translucent,
        gestures: {
          SingleDragGestureRecognizer:
              GestureRecognizerFactoryWithHandlers<SingleDragGestureRecognizer>(
            () => SingleDragGestureRecognizer(debugOwner: this),
            (SingleDragGestureRecognizer instance) {
              instance.onDragStart = (Offset position) {
                if (_currentState.menuFactor == 0 || _hidingAnimation != null) {
                  return null;
                }
                final drag = widget.menuDragProvider(
                  position,
                  instance.lastPointer!,
                );
                // When recognizer disappears the drag is not cancelled, which prevents
                // subsequent drags from
                return drag;
              };
            },
          ),
        },
        child: _Background(
          opacity: backgroundOpacity,
          backgroundBuilder:
              widget.configuration.menuConfiguration?.backgroundBuilder,
          child: Opacity(
            opacity:
                (1.0 - 0.3 * _currentState.dragFactor) * (1.0 - _hideFactor),
            child: BetterRepaintBoundary(
              key: _repaintBoundary,
              child: CustomMultiChildLayout(
                delegate: layoutDelegate,
                children: [
                  for (final item in layoutDelegate.secondaryItems)
                    LayoutId(
                      key: _secondaryLiftKeys[item.index],
                      id: item.liftChildId,
                      child: Opacity(
                        opacity: secondaryLiftAlpha,
                        child: ShadowImage(
                            image: item.liftImage,
                            shadowRadius: kShadowRadius,
                            shadowOpacity: 1.0),
                      ),
                    ),
                  for (final item in layoutDelegate.secondaryItems)
                    LayoutId(
                      id: item.dragChildId,
                      key: _secondaryDragKeys[item.index],
                      child: Opacity(
                        opacity: secondaryDragAlpha,
                        child: Transform.rotate(
                          angle: _angleForSecondaryItem(item.index) *
                              _currentState.dragFactor,
                          child: ShadowImage(
                              key: _secondaryRenderKeys[item.index],
                              image: item.dragImage,
                              shadowRadius: kShadowRadius,
                              shadowOpacity: 1.0),
                        ),
                      ),
                    ),
                  LayoutId(
                    id: layoutDelegate.primaryItem.liftChildId,
                    key: _liftKey,
                    child: Opacity(
                      opacity: liftOpacity,
                      child: ShadowImage(
                        image:
                            widget.configuration.primaryItem.liftImage.snapshot,
                        shadowRadius: kShadowRadius,
                        shadowOpacity: _currentState.liftFactor,
                      ),
                    ),
                  ),
                  if (menuConfiguration != null && _currentState.menuFactor > 0)
                    LayoutId(
                      id: layoutDelegate.menuPreviewId,
                      key: _menuPreviewKey,
                      child: RepaintBoundary(
                        child: Opacity(
                          opacity: menuOpacity,
                          child: menuPreview?.widget,
                        ),
                      ),
                    ),
                  if (menuConfiguration != null && _currentState.menuFactor > 0)
                    LayoutId(
                      key: _menuKey,
                      id: layoutDelegate.menuId,
                      child: Opacity(
                        opacity: menuOpacity,
                        child: Transform.scale(
                          alignment: _menuAlignment,
                          scale: menuOpacity * _easeOut(1.0 - _hideFactor),
                          child: menuConfiguration.menuWidgetBuilder(
                            context,
                            menuConfiguration.menuHandle.menu,
                            this,
                            _menuAlignment,
                            _menuCanScrollNotifier,
                            menuConfiguration.iconTheme,
                          ),
                        ),
                      ),
                    ),
                  LayoutId(
                    id: layoutDelegate.primaryItem.dragChildId,
                    key: _dragKey,
                    child: Opacity(
                      opacity: dragOpacity,
                      child: IgnorePointer(
                        ignoring: true,
                        child: ShadowImage(
                          shadowRadius: kShadowRadius,
                          shadowOpacity: 1.0,
                          image: layoutDelegate.primaryItem.dragImage,
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  final _menuKey = GlobalKey();
  final _menuPreviewKey = GlobalKey();
  final _liftKey = GlobalKey();
  final _dragKey = GlobalKey();

  final _secondaryDragKeys = <GlobalKey>[];
  final _secondaryLiftKeys = <GlobalKey>[];
  final _secondaryRenderKeys = <GlobalKey>[];

  double _hideFactor = 0;

  bool isMenuPreviewAtPosition(Offset globalPosition) {
    final renderBox =
        _menuPreviewKey.currentContext!.findRenderObject() as RenderBox;
    final localPosition = renderBox.globalToLocal(globalPosition);
    return renderBox.paintBounds.contains(localPosition);
  }

  void hide() {
    if (!mounted) {
      widget.onCancel;
      return;
    }
    final originalMenu = _currentState.menuFactor;
    final originalMenuOffset = _currentState.menuOverdrag;
    _hidingAnimation =
        SimpleAnimation.animate(const Duration(milliseconds: 300), (value) {
      if (!mounted) {
        return;
      }
      setState(() {
        _hideFactor = value;
        _currentState = _currentState.copyWith(
          menuFactor: ui.lerpDouble(originalMenu, 0, _easeOut(value))!,
          menuOverdrag:
              Offset.lerp(originalMenuOffset, Offset.zero, _easeOut(value))!,
        );
      });
    }, onEnd: () {
      widget.onCancel();
    });
  }

  SimpleAnimation? _hidingAnimation;
  SimpleAnimation? _resetMenuOffsetAnimation;
  SimpleAnimation? _menuDragOffsetAnimation;

  var _currentState = DragState(
    dragFactor: 0.0,
    globalPosition: Offset.zero,
    liftFactor: 0.0,
    menuFactor: 0.0,
    menuOverdrag: Offset.zero,
    menuDragOffset: 0,
  );

  void menuDragEnded(double velocity) {
    if (_currentState.menuOverdrag != Offset.zero ||
        (_currentState.menuDragOffset != 0 &&
            _currentState.menuDragOffset != 1)) {
      final originalOffset = _currentState.menuOverdrag;
      final originalDragOffset = _currentState.menuDragOffset;
      final double newDragOffset;
      if (velocity < -1000.0) {
        newDragOffset = 1.0;
      } else if (velocity > 1000.0) {
        newDragOffset = 0;
      } else {
        newDragOffset = _currentState.menuDragOffset.roundToDouble();
      }

      _resetMenuOffsetAnimation =
          SimpleAnimation.animate(const Duration(milliseconds: 150), (v) {
        final value = _easeOut(v);
        setState(() {
          _currentState = _currentState.copyWith(
            menuOverdrag: Offset.lerp(originalOffset, Offset.zero, value),
            menuDragOffset:
                ui.lerpDouble(originalDragOffset, newDragOffset, value),
          );
        });
      });
    }
  }

  bool isMenuOpened() {
    return _currentState.menuFactor > 0;
  }

  void update(DragState state) {
    _resetMenuOffsetAnimation?.cancel();
    _menuDragOffsetAnimation?.cancel;

    setState(() {
      _currentState = DragState(
        dragFactor: state.dragFactor,
        globalPosition: state.globalPosition,
        liftFactor: _easeOut(state.liftFactor),
        menuFactor: _easeOut(state.menuFactor),
        menuOverdrag: state.menuOverdrag,
        menuDragOffset: state.menuDragOffset,
      );
    });
  }

  @override
  void hideMenu({required bool itemSelected}) {
    if (itemSelected) {
      widget.onMenuItemSelected();
    }
    hide();
  }

  @override
  void didPushSubmenu() {
    if (_currentState.menuDragOffset < 1.0) {
      final originalOffset = _currentState.menuDragOffset;
      _menuDragOffsetAnimation =
          SimpleAnimation.animate(const Duration(milliseconds: 200), (v) {
        final value = _easeOut(v);
        setState(() {
          _currentState = _currentState.copyWith(
            menuDragOffset: ui.lerpDouble(originalOffset, 1.0, value),
          );
        });
      });
    }
  }
}

class _Background extends StatefulWidget {
  final Widget child;
  final double opacity;
  final Widget Function(double opacity)? backgroundBuilder;

  const _Background({
    required this.opacity,
    required this.child,
    required this.backgroundBuilder,
  });

  @override
  State<_Background> createState() => _BackgroundState();
}

class _BackgroundState extends State<_Background> {
  final _childKey = GlobalKey();

  @override
  Widget build(BuildContext context) {
    if (widget.opacity == 0) {
      return KeyedSubtree(
        key: _childKey,
        child: widget.child,
      );
    }
    return Stack(
      children: [
        if (widget.backgroundBuilder != null)
          widget.backgroundBuilder!(
            widget.opacity,
          ),
        Positioned.fill(
          child: KeyedSubtree(
            key: _childKey,
            child: widget.child,
          ),
        ),
      ],
    );
  }
}

import 'dart:math' as math;
import 'package:collection/collection.dart';
import 'package:flutter/widgets.dart';

import 'util.dart';

class MenuLayoutInput {
  MenuLayoutInput({
    required this.layoutMenu,
    required this.bounds,
    required this.primaryItem,
    required this.menuPreviewSize,
    required this.menuDragOffset,
    required this.previousLayoutId,
  });

  final Size Function(BoxConstraints) layoutMenu;
  final Rect bounds;
  final Rect primaryItem;
  final Size menuPreviewSize;
  final double menuDragOffset;
  final String? previousLayoutId;
}

class MenuLayout {
  MenuLayout({
    required this.previewRect,
    required this.menuPosition,
    required this.menuDragExtent,
    required this.canScrollMenu,
    required this.menuAlignment,
    required this.layoutId,
  });

  final String layoutId;
  final Rect previewRect;
  final MenuPosition menuPosition;
  final double menuDragExtent;
  final bool canScrollMenu;
  final AlignmentGeometry menuAlignment;
}

typedef MenuPosition = Offset Function(Rect previewRect);

const _epsilon = 0.001;

class _MenuGeometry {
  final String id;
  final Rect previewRect;
  final Size menuSize;
  final MenuPosition menuPosition;
  final AlignmentGeometry menuAlignment;

  _MenuGeometry({
    required this.id,
    required this.previewRect,
    required this.menuSize,
    required this.menuPosition,
    required this.menuAlignment,
  });

  Rect get menuRect {
    final position = menuPosition(previewRect);
    return Rect.fromLTWH(
      position.dx,
      position.dy,
      menuSize.width,
      menuSize.height,
    );
  }

  Rect get bounds => previewRect.expandToInclude(menuRect);

  bool fitsInto(Rect rect) {
    final bounds = this.bounds;
    return bounds.left + _epsilon >= rect.left &&
        bounds.right <= rect.right + _epsilon &&
        bounds.top + _epsilon >= rect.top &&
        bounds.bottom <= rect.bottom + _epsilon;
  }

  /// Try to keep the menu preview in the same position vertically as before.
  _MenuGeometry _fitIntoHorizontal(Rect rect) {
    final res = _fitInto(rect);
    final desiredPreviewRect = previewRect.moveIntoRect(rect);
    final correction =
        Offset(0, res.previewRect.center.dy - desiredPreviewRect.center.dy);

    return _MenuGeometry(
      id: res.id,
      menuAlignment: res.menuAlignment,
      menuPosition: (pos) => res.menuPosition(pos) + correction,
      menuSize: res.menuSize,
      previewRect: res.previewRect.shift(-correction),
    );
  }

  _MenuGeometry fitInto(Rect rect) {
    if (menuRect.left > previewRect.right ||
        menuRect.right < previewRect.left) {
      return _fitIntoHorizontal(rect);
    } else {
      return _fitInto(rect);
    }
  }

  _MenuGeometry _fitInto(Rect rect) {
    final bounds = this.bounds;
    final dx1 = bounds.left < rect.left ? rect.left - bounds.left : 0.0;
    final dx2 = bounds.right > rect.right ? rect.right - bounds.right : 0.0;
    final dy1 = bounds.top < rect.top ? rect.top - bounds.top : 0.0;
    final dy2 = bounds.bottom > rect.bottom ? rect.bottom - bounds.bottom : 0.0;
    final offset = Offset(dx1 + dx2, dy1 + dy2);
    return _MenuGeometry(
      id: id,
      previewRect: previewRect.shift(offset),
      menuSize: menuSize,
      menuPosition: menuPosition,
      menuAlignment: menuAlignment,
    );
  }
}

/// Picks the geometry that fits best inside the bounds and shifts just enough
/// to fit in the bounds.
_MenuGeometry _bestFitGeometry(
  Rect bounds,
  List<_MenuGeometry> geometry,
  String? previousLayoutId,
) {
  if (previousLayoutId != null) {
    final previous =
        geometry.firstWhereOrNull((element) => element.id == previousLayoutId);
    if (previous != null) {
      return previous.fitInto(bounds);
    }
  }
  // Try to find first element that fully fits
  final firstThatFits =
      geometry.firstWhereOrNull((element) => element.fitsInto(bounds));
  if (firstThatFits != null) {
    return firstThatFits;
  }

  final geometryThatFits = geometry
      .where((element) => element.bounds.size <= bounds.size.inflate(_epsilon))
      .toList(growable: false);

  if (geometryThatFits.isEmpty) {
    return geometry.first;
  }

  // Find which ever geometry needs least adjustment relative to preview rect
  // to fit into bounds
  final best = geometryThatFits.reduce((value, element) {
    final v1 = value.fitInto(bounds);
    final v2 = element.fitInto(bounds);
    final d1 =
        (v1.previewRect.center - value.previewRect.center).distanceSquared;
    final d2 =
        (v2.previewRect.center - element.previewRect.center).distanceSquared;
    return d1 <= d2 + _epsilon ? value : element;
  });
  return best.fitInto(bounds);
}

abstract class MenuLayoutStrategy {
  MenuLayout layout(MenuLayoutInput input);

  static MenuLayoutStrategy forSize(Size screenSize) {
    if (screenSize.shortestSide < 550) {
      // phone layout
      if (screenSize.height > screenSize.width) {
        return _MenuLayoutMobilePortrait();
      } else {
        return _MenuLayout(allowVerticalAttachment: false);
      }
    } else {
      return _MenuLayout(allowVerticalAttachment: true);
    }
  }
}

const _kMenuSpacing = 15.0;

class _MenuLayout extends MenuLayoutStrategy {
  _MenuLayout({
    required this.allowVerticalAttachment,
  });

  final bool allowVerticalAttachment;

  @override
  MenuLayout layout(MenuLayoutInput input) {
    final menuSize = input.layoutMenu(BoxConstraints.loose(input.bounds.size));
    final spaceForPreview = Size(
        input.bounds.width - menuSize.width - _kMenuSpacing,
        input.bounds.height);
    final previewSize = input.menuPreviewSize.fitInto(spaceForPreview);
    final previewRect = Rect.fromCenter(
      center: input.primaryItem.center,
      width: previewSize.width,
      height: previewSize.height,
    );

    final vertical = [
      // Aligned to bottom left corner
      _MenuGeometry(
        id: 'vertical-bottom-left',
        previewRect: previewRect,
        menuSize: menuSize,
        menuPosition: (previewRect) => Offset(
          previewRect.left,
          previewRect.bottom + _kMenuSpacing,
        ),
        menuAlignment: Alignment.topLeft,
      ),
      // Aligned to bottom right corner
      _MenuGeometry(
        id: 'vertical-bottom-right',
        previewRect: previewRect,
        menuSize: menuSize,
        menuPosition: (previewRect) => Offset(
          previewRect.right - menuSize.width,
          previewRect.bottom + _kMenuSpacing,
        ),
        menuAlignment: Alignment.topRight,
      ),
      // Aligned to top left corner
      _MenuGeometry(
        id: 'vertical-top-left',
        previewRect: previewRect,
        menuSize: menuSize,
        menuPosition: (previewRect) => Offset(
          previewRect.left,
          previewRect.top - _kMenuSpacing - menuSize.height,
        ),
        menuAlignment: Alignment.bottomLeft,
      ),
      // Aligned to top right corner
      _MenuGeometry(
        id: 'vertical-top-right',
        previewRect: previewRect,
        menuSize: menuSize,
        menuPosition: (previewRect) => Offset(
          previewRect.right - menuSize.width,
          previewRect.top - _kMenuSpacing - menuSize.height,
        ),
        menuAlignment: Alignment.bottomRight,
      ),
    ];

    final horizontal = [
      // Aligned to top right corner
      _MenuGeometry(
        id: 'horizontal-top-right',
        previewRect: previewRect,
        menuSize: menuSize,
        menuPosition: (previewRect) => Offset(
          previewRect.right + _kMenuSpacing,
          previewRect.top,
        ),
        menuAlignment: Alignment.topLeft,
      ),
      // Aligned to bottom right corner
      _MenuGeometry(
        id: 'horizontal-bottom-right',
        previewRect: previewRect,
        menuSize: menuSize,
        menuPosition: (previewRect) => Offset(
          previewRect.right + _kMenuSpacing,
          previewRect.bottom - menuSize.height,
        ),
        menuAlignment: Alignment.bottomLeft,
      ),
      // Aligned to top left corner
      _MenuGeometry(
        id: 'horizontal-top-left',
        previewRect: previewRect,
        menuSize: menuSize,
        menuPosition: (previewRect) => Offset(
          previewRect.left - _kMenuSpacing - menuSize.width,
          previewRect.top,
        ),
        menuAlignment: Alignment.topRight,
      ),
      // Aligned to bottom left corner
      _MenuGeometry(
        id: 'horizontal-bottom-left',
        previewRect: previewRect,
        menuSize: menuSize,
        menuPosition: (previewRect) => Offset(
          previewRect.left - _kMenuSpacing - menuSize.width,
          previewRect.bottom - menuSize.height,
        ),
        menuAlignment: Alignment.bottomRight,
      ),
    ];

    final List<_MenuGeometry> geometries;
    if (allowVerticalAttachment &&
        input.menuPreviewSize.width > input.menuPreviewSize.height) {
      // prefer vertical attachment on wide previews
      geometries = [
        ...vertical,
        ...horizontal,
      ];
    } else if (allowVerticalAttachment) {
      // prefer horizontal attachment on wide previews
      geometries = [
        ...horizontal,
        ...vertical,
      ];
    } else {
      geometries = horizontal;
    }

    final geometry = _bestFitGeometry(
      input.bounds,
      geometries,
      input.previousLayoutId,
    );

    return MenuLayout(
      layoutId: geometry.id,
      previewRect: geometry.previewRect,
      menuPosition: geometry.menuPosition,
      menuDragExtent: 0.0,
      canScrollMenu: true,
      menuAlignment: geometry.menuAlignment,
    );
  }
}

class _MenuLayoutMobilePortrait extends MenuLayoutStrategy {
  @override
  MenuLayout layout(MenuLayoutInput input) {
    final menuPreviewSizeMin = input.menuPreviewSize
        .fitInto(Size(input.bounds.width, input.bounds.height / 4));
    final menuPreviewSizeMax = input.menuPreviewSize
        .fitInto(Size(input.bounds.width, input.bounds.height * 3 / 4));

    final menuSize = input.layoutMenu(BoxConstraints.loose(Size(
      input.bounds.width,
      input.bounds.height - menuPreviewSizeMin.height - _kMenuSpacing,
    )));

    final menuOverflow = math.max(
        menuPreviewSizeMax.height +
            _kMenuSpacing +
            menuSize.height -
            input.bounds.height,
        0.0);

    final verticalCorrection = -math.max(
        input.primaryItem.center.dy -
            input.bounds.top +
            menuPreviewSizeMin.height / 2 +
            _kMenuSpacing +
            menuSize.height -
            input.bounds.height,
        0.0);

    final menuDragOffset = input.menuDragOffset * menuOverflow;

    final actualMenuPreviewSize = input.menuPreviewSize.fitInto(
        Size(input.bounds.width, menuPreviewSizeMax.height - menuDragOffset));

    final menuPreviewRectMax = Rect.fromCenter(
            center: input.primaryItem.center,
            width: menuPreviewSizeMax.width,
            height: menuPreviewSizeMax.height)
        .translate(0, verticalCorrection)
        .fitIntoRect(input.bounds);

    // left aligned
    final previewRect1 = menuPreviewRectMax.copyWith(
      width: actualMenuPreviewSize.width,
      height: actualMenuPreviewSize.height,
    );

    // right aligned
    final previewRect2 = previewRect1.copyWith(
      left: menuPreviewRectMax.right - previewRect1.width,
    );

    // Bounds adjusted to fit overflow in so that _bestFitGeomety doesn't try to move things
    // vertically
    final adjustedBounds =
        input.bounds.copyWith(height: input.bounds.height + menuOverflow);
    final geometry = _bestFitGeometry(
      adjustedBounds,
      [
        _MenuGeometry(
          id: 'geometry-1',
          previewRect: previewRect1,
          menuSize: menuSize,
          menuPosition: (previewRect) => Offset(
            previewRect.left,
            previewRect.bottom + _kMenuSpacing,
          ),
          menuAlignment: Alignment.topLeft,
        ),
        _MenuGeometry(
          id: 'geometry-2',
          previewRect: previewRect2,
          menuSize: menuSize,
          menuPosition: (previewRect) => Offset(
            previewRect.right - menuSize.width,
            previewRect.bottom + _kMenuSpacing,
          ),
          menuAlignment: Alignment.topRight,
        ),
      ],
      input.previousLayoutId,
    );

    return MenuLayout(
      layoutId: geometry.id,
      previewRect: geometry.previewRect,
      menuDragExtent: menuOverflow,
      canScrollMenu: menuOverflow == 0.0 || input.menuDragOffset == 1.0,
      menuPosition: geometry.menuPosition,
      menuAlignment: geometry.menuAlignment,
    );
  }
}

import 'dart:ui' as ui;
import 'dart:math' as math;

import 'package:flutter/rendering.dart';
import 'package:pixel_snap/pixel_snap.dart';

import '../widget_snapshot/widget_snapshot.dart';
import 'drag_state_machine.dart';
import 'overlay_layout_strategy.dart';
import 'util.dart';

class LayoutItemConfiguration {
  LayoutItemConfiguration({
    required this.index,
    required this.liftChildId,
    required this.dragChildId,
    required this.liftRect,
    required this.dragSize,
    required this.liftImage,
    required this.dragImage,
  });

  final int index;
  final Object liftChildId;
  final Object dragChildId;
  final Rect liftRect;
  final Size dragSize;
  final WidgetSnapshot liftImage;
  final WidgetSnapshot dragImage;
}

class OverlayLayoutState {
  String? _previousLayoutId;
}

class OverlayLayoutDelegate extends MultiChildLayoutDelegate {
  OverlayLayoutDelegate({
    required this.padding,
    required this.primaryItem,
    required this.secondaryItems,
    required this.menuPreviewSize,
    required this.menuPreviewId,
    required this.menuId,
    required this.dragState,
    required this.menuDragExtentSetter,
    required this.canScrollMenuSetter,
    required this.menuAlignmentSetter,
    required this.pixelSnap,
    required this.hasCustomMenuPreview,
    required this.layoutState,
  });

  final EdgeInsets padding;
  final LayoutItemConfiguration primaryItem;
  final List<LayoutItemConfiguration> secondaryItems;
  final Size? menuPreviewSize;
  final Object menuPreviewId;
  final Object menuId;
  final DragState dragState;
  final ValueSetter<double> menuDragExtentSetter;
  final ValueSetter<bool> canScrollMenuSetter;
  final ValueSetter<AlignmentGeometry> menuAlignmentSetter;
  final PixelSnap pixelSnap;
  final bool hasCustomMenuPreview;
  final OverlayLayoutState layoutState;

  double _dampen(double value) {
    return math.log(value * value + 1) / math.ln10;
  }

  Offset get _menuOverdrag {
    return Offset(
      _dampen(dragState.menuOverdrag.dx.abs()) * dragState.menuOverdrag.dx.sign,
      _dampen(dragState.menuOverdrag.dy.abs()) * dragState.menuOverdrag.dy.sign,
    );
  }

  double _inflateFactorForSize(Size size) {
    final ratio = math
        .max(primaryItem.liftRect.width / size.width,
            primaryItem.liftRect.height / size.height)
        .clamp(0.0, 1.0);
    const maxFactor = 1.15;
    const minFactor = 1.04;
    return ui.lerpDouble(maxFactor, minFactor, ratio)!;
  }

  Rect _computePrimaryItemRect({
    required Rect bounds,
    required Rect? menuPreviewRect,
    required double liftFactor,
  }) {
    final inflateFactor = 1.0 + (liftFactor - 1.0) * dragState.liftFactor;
    var rect = primaryItem.liftRect.inflateBy(inflateFactor);

    // If there is no custom menu preview use the size from lift rect.
    // This is similar behavior to iOS.
    if (!hasCustomMenuPreview && menuPreviewRect != null) {
      menuPreviewRect =
          menuPreviewRect.inflateBy(inflateFactor).fitIntoRect(bounds);
    }

    if (hasChild(menuPreviewId) && dragState.menuFactor > 0) {
      assert(menuPreviewRect != null);
      final menuOverdrag = _menuOverdrag;
      final menuRect =
          menuPreviewRect!.translate(menuOverdrag.dx, menuOverdrag.dy);
      rect = Rect.lerp(rect, menuRect, dragState.menuFactor)!;
    }
    if (dragState.dragFactor > 0) {
      final finalDragRect = Rect.fromCenter(
        center: dragState.globalPosition,
        width: primaryItem.dragSize.width,
        height: primaryItem.dragSize.height,
      );
      rect = Rect.lerp(rect, finalDragRect, dragState.dragFactor)!;
    }
    return rect;
  }

  Rect _computeSecondaryItemRect(LayoutItemConfiguration item) {
    var rect = item.liftRect;
    if (dragState.dragFactor > 0) {
      final finalDragRect = Rect.fromCenter(
        center: dragState.globalPosition,
        width: item.dragSize.width,
        height: item.dragSize.height,
      );
      rect = Rect.lerp(rect, finalDragRect, dragState.dragFactor)!;
    }
    return rect;
  }

  void _layoutChild(Object childId, Rect rect) {
    layoutChild(childId, BoxConstraints.tight(rect.size));
    positionChild(childId, rect.topLeft.pixelSnap(pixelSnap));
  }

  EdgeInsets _insetsForSize(ui.Size size) {
    return padding + const EdgeInsets.all(20);
  }

  @override
  void performLayout(ui.Size size) {
    MenuLayoutStrategy? strategy;
    Rect? menuPreviewRect;
    final insets = _insetsForSize(size);
    final bounds =
        insets.deflateRect(Rect.fromLTWH(0, 0, size.width, size.height));
    Size? menuSize;
    MenuPosition? menuPosition;
    if (hasChild(menuPreviewId)) {
      strategy = MenuLayoutStrategy.forSize(size);
      final layout = strategy.layout(
        MenuLayoutInput(
            previousLayoutId: layoutState._previousLayoutId,
            layoutMenu: (constraints) {
              menuSize = layoutChild(menuId, constraints);
              return menuSize!;
            },
            bounds: bounds,
            primaryItem: primaryItem.liftRect,
            menuPreviewSize: menuPreviewSize!,
            menuDragOffset: dragState.menuDragOffset),
      );
      menuDragExtentSetter(layout.menuDragExtent);
      canScrollMenuSetter(layout.canScrollMenu);
      menuAlignmentSetter(layout.menuAlignment);
      menuPreviewRect = layout.previewRect;
      menuPosition = layout.menuPosition;
      layoutState._previousLayoutId = layout.layoutId;
    }

    final primaryItemRect = _computePrimaryItemRect(
      bounds: bounds,
      menuPreviewRect: menuPreviewRect,
      liftFactor: _inflateFactorForSize(size),
    );
    _layoutChild(primaryItem.liftChildId, primaryItemRect);
    _layoutChild(primaryItem.dragChildId, primaryItemRect);
    if (hasChild(menuPreviewId)) {
      _layoutChild(menuPreviewId, primaryItemRect);
    }

    for (final item in secondaryItems) {
      final rect = _computeSecondaryItemRect(item);
      _layoutChild(item.liftChildId, rect);
      _layoutChild(item.dragChildId, rect);
    }

    if (hasChild(menuId)) {
      assert(menuPosition != null);
      final offset = menuPosition!(primaryItemRect) - _menuOverdrag;
      positionChild(menuId, offset.pixelSnap(pixelSnap));
    }
  }

  @override
  bool shouldRelayout(covariant MultiChildLayoutDelegate oldDelegate) {
    return this != oldDelegate;
  }
}

import 'package:flutter/rendering.dart';

/// Represents currently running long-press interaction. The interaction starts at long-press
/// and extends all the way until menu dismissal or end of drag and drop.
class LongPressSession {
  static int _depth = 0;

  static bool get active => _depth > 0;

  /// Register cleanup callback executed when current long press session ends.
  static void onCleanup(VoidCallback cb) {
    assert(_depth > 0);
    _cleanupCallbacks.add(cb);
  }

  static final _cleanupCallbacks = <VoidCallback>[];

  /// Runs the action block from within a long press session.
  static T run<T>(T Function() action) {
    _depth++;
    try {
      return action();
    } finally {
      _depth--;
      if (_depth == 0) {
        _cleanup();
      }
    }
  }

  /// Extends the length of current long press session until the future completes.
  static Future<T> extend<T>(Future<T> Function() future) async {
    _depth++;
    try {
      return await future();
    } finally {
      _depth--;
      if (_depth == 0) {
        _cleanup();
      }
    }
  }

  static void _cleanup() {
    for (final cb in _cleanupCallbacks) {
      cb();
    }
    _cleanupCallbacks.clear();
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';
import 'package:flutter/widgets.dart';

import 'package:device_info_plus/device_info_plus.dart';

import '../drag.dart';
import '../drop.dart';
import '../menu.dart';
import '../widget_snapshot/widget_snapshot.dart';
import '../gesture/single_drag.dart';

import 'long_press_session.dart';
import 'interaction_session.dart';
import 'delayed_drag.dart';

int _nextMenuConfigurationId = 1;

class MenuPreviewWidget {
  final Widget widget;
  final Size size;

  MenuPreviewWidget({
    required this.widget,
    required this.size,
  });
}

class LongPressHandler {
  static Future<LongPressHandler> create() async {
    return LongPressHandler._(
      dragContext: await DragContext.instance(),
      menuContext: await MenuContext.instance(),
    );
  }

  SingleDrag? dragGestureForPosition({
    required BuildContext context,
    required Offset position,
    required int pointer,
  }) {
    if (LongPressSession.active) {
      return null;
    }
    return LongPressSession.run(() {
      final previewUpdateNotifier = ValueNotifier<WidgetSnapshot?>(null);
      final session = _FakeDragSession();
      LongPressSession.onCleanup(session._dispose);

      final dragConfiguration =
          _dragContext.delegate?.getConfigurationForDragRequest(
        location: position,
        session: session,
      );
      final menuConfiguration = _menuContext.delegate?.getMenuConfiguration(
        MobileMenuConfigurationRequest(
          configurationId: _nextMenuConfigurationId++,
          location: position,
          previewImageSetter: (image) {
            previewUpdateNotifier.value = image;
          },
        ),
      );
      if (dragConfiguration == null && menuConfiguration == null) {
        return null;
      }
      final dragFuture = _dragForConfigurationFutures(
        dragConfiguration: dragConfiguration,
        menuConfiguration: menuConfiguration,
        dragSession: session,
        pointer: pointer,
        context: context,
        position: position,
        previewUpdateListenable: previewUpdateNotifier,
      );
      return DelayedDrag(LongPressSession.extend(() => dragFuture));
    });
  }

  DragItem _findPrimaryItem(DragConfiguration configuration, Offset position) {
    for (final item in configuration.items) {
      final image = item.liftImage ?? item.image;
      if (image.rect.contains(position)) {
        return item;
      }
    }
    return configuration.items.reduce((v1, v2) {
      final image1 = v1.liftImage ?? v1.image;
      final image2 = v2.liftImage ?? v2.image;
      final distance1 = (image1.rect.center - position).distanceSquared;
      final distance2 = (image2.rect.center - position).distanceSquared;
      return distance1 < distance2 ? v1 : v2;
    });
  }

  Future<SingleDrag?> _dragForConfigurationFutures({
    required Future<DragConfiguration?>? dragConfiguration,
    required Future<MobileMenuConfiguration?>? menuConfiguration,
    required _FakeDragSession dragSession,
    required int pointer,
    required BuildContext context,
    required Offset position,
    required ValueListenable<WidgetSnapshot?> previewUpdateListenable,
  }) async {
    final drag = await dragConfiguration;
    final menu = await menuConfiguration;
    if (drag == null && menu == null) {
      return null;
    }
    return LongPressSession.extend(() async {
      LongPressSession.onCleanup(() {
        drag?.disposeImages();
        menu?.dispose();
      });
      if (!context.mounted) {
        return null;
      }
      return await _dragForConfiguration(
        dragConfiguration: drag,
        menuConfiguration: menu,
        dragSession: dragSession,
        pointer: pointer,
        context: context,
        position: position,
        previewUpdateListenable: previewUpdateListenable,
      );
    });
  }

  Future<SingleDrag?> _dragForConfiguration({
    required DragConfiguration? dragConfiguration,
    required MobileMenuConfiguration? menuConfiguration,
    required _FakeDragSession dragSession,
    required int pointer,
    required BuildContext context,
    required Offset position,
    required ValueListenable<WidgetSnapshot?> previewUpdateListenable,
  }) async {
    final ItemConfiguration primaryItem;
    final List<ItemConfiguration> secondaryItems;
    final DragStartCallback? onDragStart;

    bool successfullyTransitionedToDrag = false;

    DeviceInfoPlugin deviceInfoPlugin = DeviceInfoPlugin();
    final deviceInfo = await deviceInfoPlugin.deviceInfo;

    // ignore: use_build_context_synchronously
    if (!context.mounted) {
      return null;
    }

    LongPressSession.onCleanup(() {
      if (!successfullyTransitionedToDrag && dragConfiguration != null) {
        for (final item in dragConfiguration.items) {
          item.dataProvider.dispose();
        }
      }
    });

    if (dragConfiguration != null && dragConfiguration.items.isNotEmpty) {
      final primary = _findPrimaryItem(dragConfiguration, position);
      primaryItem = ItemConfiguration(
          liftImage: menuConfiguration?.liftImage ??
              primary.liftImage ??
              primary.image.retain(),
          dragImage: primary.image.snapshot);
      secondaryItems = dragConfiguration.items
          .where((e) => e != primary)
          .map((e) => ItemConfiguration(
                liftImage: e.liftImage ?? e.image.retain(),
                dragImage: e.image.snapshot,
              ))
          .toList(growable: false);

      onDragStart = (
        offset,
        pointer,
        snapshot,
        draggingStarted,
      ) {
        final realSession = _dragContext.newSession(pointer: pointer);
        dragSession.startDrag(realSession);

        final dragCompleter = Completer();

        void maybeStarted() {
          if (!successfullyTransitionedToDrag) {
            successfullyTransitionedToDrag = true;
            draggingStarted();
            if (realSession.dragCompleted.value == null) {
              realSession.dragCompleted.addListener(() {
                dragCompleter.complete();
              });
              LongPressSession.extend(() => dragCompleter.future);
            }
          }
        }

        // How many location changed events to ignore before hiding our placeholder.
        // On some Android version (30) the drag avatar is not displayed until the second
        // location change event.
        var ignoreEventCount = 0;

        if (deviceInfo is AndroidDeviceInfo) {
          if (deviceInfo.version.sdkInt <= 30) {
            ignoreEventCount = 1;
          }
        }

        final targetedImage = TargetedWidgetSnapshot(
            snapshot,
            Rect.fromCenter(
                center: primary.image.rect.center,
                width: snapshot.pointWidth,
                height: snapshot.pointHeight));

        void lastScreenLocationChanged() {
          if (ignoreEventCount == 0) {
            maybeStarted();
            realSession.lastScreenLocation
                .removeListener(lastScreenLocationChanged);
          }
          --ignoreEventCount;
        }

        realSession.lastScreenLocation.addListener(lastScreenLocationChanged);
        realSession.dragCompleted.addListener(maybeStarted);
        if (context.mounted) {
          LongPressSession.extend(
            () => _dragContext.startDrag(
                buildContext: context,
                session: realSession,
                configuration: dragConfiguration,
                position: offset,
                combinedDragImage: targetedImage),
          );
        }
      };
    } else if (menuConfiguration != null) {
      primaryItem = ItemConfiguration(
        liftImage: menuConfiguration.liftImage,
        dragImage: menuConfiguration.liftImage.snapshot.retain(),
      );
      secondaryItems = [];
      onDragStart = null;
    } else {
      return null;
    }

    final finisherCompleter = Completer();
    LongPressSession.extend(() => finisherCompleter.future);

    final DragInteractionMenuConfiguration? interactionMenuConfiguration;
    if (menuConfiguration != null) {
      MenuPreviewWidget createMenuPreview(Size size, WidgetSnapshot? snapshot) {
        return MenuPreviewWidget(
          size: size,
          widget: menuConfiguration.previewBuilder(size, snapshot),
        );
      }

      final MenuPreviewWidget menuPreviewWidget;
      final bool hasCustomMenuPreview;

      if (menuConfiguration.previewSize != null) {
        // deferred preview
        menuPreviewWidget =
            createMenuPreview(menuConfiguration.previewSize!, null);
        hasCustomMenuPreview = true;
      } else if (menuConfiguration.previewImage != null) {
        menuPreviewWidget = createMenuPreview(
            menuConfiguration.previewImage!.pointSize,
            menuConfiguration.previewImage);
        hasCustomMenuPreview = true;
      } else {
        menuPreviewWidget = createMenuPreview(
            menuConfiguration.liftImage.snapshot.pointSize,
            menuConfiguration.liftImage.snapshot);
        hasCustomMenuPreview = false;
      }

      final menuPreview = ValueNotifier(menuPreviewWidget);

      void previewUpdateListener() {
        final image = previewUpdateListenable.value;
        if (image != null) {
          LongPressSession.onCleanup(() {
            image.dispose();
          });
          menuPreview.value = createMenuPreview(
            image.pointSize,
            image,
          );
        }
      }

      previewUpdateListenable.addListener(previewUpdateListener);
      LongPressSession.onCleanup(() {
        previewUpdateListenable.removeListener(previewUpdateListener);
      });

      interactionMenuConfiguration = DragInteractionMenuConfiguration(
        hasCustomMenuPreview: hasCustomMenuPreview,
        menuHandle: menuConfiguration.handle,
        menuWidgetBuilder: menuConfiguration.menuWidgetBuilder,
        menuPreview: menuPreview,
        backgroundBuilder: menuConfiguration.backgroundBuilder,
        iconTheme: menuConfiguration.iconTheme,
        onMenuShown: () {
          _menuContext.delegate?.onShowMenu(menuConfiguration.configurationId);
        },
        onMenuHidden: (response) {
          _menuContext.delegate
              ?.onHideMenu(menuConfiguration.configurationId, response);
        },
        onMenuPreviewTapped: () {
          _menuContext.delegate?.onPreviewAction(
            menuConfiguration.configurationId,
          );
        },
      );
    } else {
      interactionMenuConfiguration = null;
    }

    final interactionConfiguration = DragInteractionConfiguration(
      menuConfiguration: interactionMenuConfiguration,
      primaryItem: primaryItem,
      secondaryItems: secondaryItems,
      onBeginTransitionToDrag: () {
        dragSession.beginDragging();
      },
      onDidNotFinishTransitionToDrag: () {
        dragSession.cancelDragging();
      },
      onDragStart: onDragStart,
      onFinished: () {
        finisherCompleter.complete();
      },
    );
    return DragInteractionSession(
      buildContext: context,
      configuration: interactionConfiguration,
    ).intoDrag(position, pointer);
  }

  final DragContext _dragContext;
  final MenuContext _menuContext;

  LongPressHandler._({
    required DragContext dragContext,
    required MenuContext menuContext,
  })  : _dragContext = dragContext,
        _menuContext = menuContext;
}

class _FakeDragSession extends DragSession {
  _FakeDragSession();

  DragSession? original;

  final _dragCompleted = ValueNotifier<DropOperation?>(null);
  final _dragging = ValueNotifier<bool>(false);
  final _lastScreenLocation = ValueNotifier<Offset?>(null);

  @override
  ValueListenable<DropOperation?> get dragCompleted => _dragCompleted;

  @override
  ValueListenable<bool> get dragging => _dragging;

  @override
  ValueListenable<Offset?> get lastScreenLocation => _lastScreenLocation;

  void startDrag(DragSession original) {
    this.original = original;
    original.dragCompleted.addListener(_originalDragCompleted);
    original.lastScreenLocation.addListener(() {
      _lastScreenLocation.value = original.lastScreenLocation.value;
    });
  }

  void _originalDragCompleted() {
    _dragging.value = false;
    _dragCompleted.value = original!.dragCompleted.value;
  }

  void _dispose() {
    original?.dragCompleted.removeListener(_originalDragCompleted);
    _dragCompleted.dispose();
    _dragging.dispose();
    _lastScreenLocation.dispose();
  }

  void beginDragging() {
    _dragging.value = true;
  }

  void cancelDragging() {
    if (_dragging.value) {
      _dragging.value = false;
      _dragCompleted.value = DropOperation.none;
    }
  }

  @override
  Future<List<Object?>?> getLocalData() {
    return original?.getLocalData() ?? Future.value(null);
  }
}

import 'package:flutter/foundation.dart';
import 'package:flutter/widgets.dart';

import '../gesture/multi_touch_detector.dart';
import '../menu.dart';
import '../menu_model.dart';
import '../widget_snapshot/widget_snapshot.dart';
import '../gesture/single_drag.dart';
import 'long_press_handler.dart';
import 'drag_state_machine.dart';
import 'overlay_widget.dart';

typedef DragStartCallback = void Function(
  Offset globalPosition,
  int? pointer,
  WidgetSnapshot compositeSnapshot,
  VoidCallback draggingStarted,
);

class ItemConfiguration {
  ItemConfiguration({
    required this.liftImage,
    required this.dragImage,
  });

  final TargetedWidgetSnapshot liftImage;
  final WidgetSnapshot dragImage;
}

class DragInteractionMenuConfiguration {
  DragInteractionMenuConfiguration({
    required this.hasCustomMenuPreview,
    required this.iconTheme,
    required this.backgroundBuilder,
    required this.menuPreview,
    required this.menuHandle,
    required this.menuWidgetBuilder,
    required this.onMenuShown,
    required this.onMenuHidden,
    required this.onMenuPreviewTapped,
  });

  final MenuHandle menuHandle;
  final IconThemeData iconTheme;
  final MobileMenuWidgetFactory menuWidgetBuilder;
  final Widget Function(double opacity) backgroundBuilder;
  final ValueListenable<MenuPreviewWidget?> menuPreview;
  final bool hasCustomMenuPreview;
  final VoidCallback onMenuShown;
  final ValueSetter<MenuResult> onMenuHidden;
  final VoidCallback onMenuPreviewTapped;
}

class DragInteractionConfiguration {
  DragInteractionConfiguration({
    required this.primaryItem,
    required this.secondaryItems,
    required this.onBeginTransitionToDrag,
    required this.onDidNotFinishTransitionToDrag,
    required this.onDragStart,
    required this.onFinished,
    required this.menuConfiguration,
  });

  final ItemConfiguration primaryItem;
  final List<ItemConfiguration> secondaryItems;
  final VoidCallback onBeginTransitionToDrag;
  final VoidCallback onDidNotFinishTransitionToDrag;
  final DragStartCallback? onDragStart;
  final VoidCallback onFinished;
  final DragInteractionMenuConfiguration? menuConfiguration;
}

class DragInteractionSession implements DragDelegate {
  bool _menuItemSelected = false;

  DragInteractionSession({
    required BuildContext buildContext,
    required this.configuration,
  }) {
    final overlay = Overlay.of(buildContext, rootOverlay: true);
    _entry = OverlayEntry(
      builder: (context) {
        return OverlayWidget(
          key: _key,
          configuration: configuration,
          menuDragProvider: _createDragForMenu,
          onMenuItemSelected: () {
            _menuItemSelected = true;
          },
          onCancel: cancel,
        );
      },
      opaque: false,
    );
    overlay.insert(_entry);
  }

  double _menuDragExtent() => _key.currentState?.menuDragExtent ?? 0;

  SingleDrag intoDrag(Offset offset, int pointer) {
    return DragInteractionDrag(
        delegate: this,
        pointer: pointer,
        initialOffset: offset,
        menuDragExtent: _menuDragExtent,
        initialMenuDragOffset: 0);
  }

  DragInteractionConfiguration configuration;

  SingleDrag _createDragForMenu(Offset offset, int pointer) {
    return DragInteractionDrag(
      delegate: this,
      pointer: pointer,
      initialOffset: offset,
      menuDragExtent: _menuDragExtent,
      initialMenuDragOffset: _key.currentState?.menuDragOffset ?? 0,
    );
  }

  final GlobalKey<OverlayWidgetState> _key = GlobalKey();
  late OverlayEntry _entry;

  bool _menuHidden = false;
  bool _menuShown = false;

  bool _isDone = false;

  void _done() {
    if (_isDone) {
      return;
    }
    _isDone = true;

    if (!_menuHidden) {
      configuration.menuConfiguration?.onMenuHidden(MenuResult(
        itemSelected: _menuItemSelected,
      ));
      _menuHidden = true;
    }
    _entry.remove();
    configuration.onFinished();
  }

  @override
  @protected
  void beginDrag(Offset globalPosition, int? pointer) {
    WidgetsBinding.instance.addPostFrameCallback((timeStamp) {
      final snapshot = _key.currentState?.getSnapshot();
      if (snapshot == null) {
        _done();
      } else {
        configuration.onDragStart?.call(globalPosition, pointer, snapshot, () {
          _done();
        });
      }
    });
  }

  @override
  void beginTransitonToMenu() {
    configuration.menuConfiguration?.onMenuShown();
    _menuShown = true;
  }

  @override
  void beginTransitionToDrag() {
    if (_menuShown) {
      configuration.menuConfiguration?.onMenuHidden(MenuResult(
        itemSelected: false,
      ));
      _menuHidden = true;
      _menuShown = false;
    }
    configuration.onBeginTransitionToDrag();
  }

  @override
  void didNotFinishTransitionToDrag() {
    configuration.onDidNotFinishTransitionToDrag();
  }

  @override
  void onTapUp(Offset globalPosition) {
    final inPreview =
        _key.currentState?.isMenuPreviewAtPosition(globalPosition) ?? false;
    if (inPreview) {
      configuration.menuConfiguration?.onMenuPreviewTapped();
    }
    _key.currentState?.hide();
  }

  @override
  @protected
  void cancel() {
    _done();
  }

  @override
  @protected
  bool hasMenu() {
    return configuration.menuConfiguration != null;
  }

  @override
  bool canTransitionToDrag() {
    // Transition to drag in Android with multi touch active messes
    // up touch events and potentially locks up the application.
    if (MultiTouchDetector.isMultiTouchActive()) {
      return false;
    }
    return configuration.onDragStart != null;
  }

  @override
  @protected
  bool isMenuOpened() {
    return _key.currentState?.isMenuOpened() ?? false;
  }

  @override
  @protected
  void menuDragEnded(double velocity) {
    _key.currentState?.menuDragEnded(velocity);
  }

  @override
  @protected
  void updateState(DragState state) {
    _key.currentState?.update(state);
  }
}

import 'dart:math';

import 'package:flutter/scheduler.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

import '../gesture/single_drag.dart';

class DragState {
  DragState({
    required this.liftFactor,
    required this.menuFactor,
    required this.dragFactor,
    required this.menuOverdrag,
    required this.menuDragOffset,
    required this.globalPosition,
  });

  /// Transition from inactive (0.0) to fully lifted (1.0)
  final double liftFactor;

  /// Transition from lifted (lift factor will stay the same 0.0 - 1.0) to
  /// menu.
  final double menuFactor;

  /// Transition from lifted or menu (will stay the same, within 0.0 - 1.0)
  /// to drag.
  final double dragFactor;

  /// Menu offset while menu is being dragged but before transition to drag.
  final Offset menuOverdrag;

  /// Offset for draggable menus. Long menus need to be dragged first in order
  /// to be fully visible and scrollable.
  /// 0.0 means menu is fully scrolled away or not draggable, 1.0 means
  /// menu is fully visible (when draggable).
  final double menuDragOffset;

  /// Touch position in global coordinates
  final Offset globalPosition;

  copyWith({
    double? liftFactor,
    double? menuFactor,
    double? dragFactor,
    Offset? menuOverdrag,
    double? menuDragOffset,
    Offset? globalPosition,
  }) {
    return DragState(
      liftFactor: liftFactor ?? this.liftFactor,
      menuFactor: menuFactor ?? this.menuFactor,
      dragFactor: dragFactor ?? this.dragFactor,
      menuOverdrag: menuOverdrag ?? this.menuOverdrag,
      menuDragOffset: menuDragOffset ?? this.menuDragOffset,
      globalPosition: globalPosition ?? this.globalPosition,
    );
  }
}

abstract class DragDelegate {
  void updateState(DragState state);
  void menuDragEnded(double velocity);
  void cancel();
  void beginTransitonToMenu();
  void beginTransitionToDrag();
  void didNotFinishTransitionToDrag();
  void beginDrag(Offset globalPosition, int? pointer);
  void onTapUp(Offset globalPosition);

  bool canTransitionToDrag();
  bool isMenuOpened();
  bool hasMenu();
}

enum _State {
  none,
  lifting,
  lifted,
  liftedToMenu,
  menu,
  toDrag,
  waitingCancellationAfterDrag,
  cancelLift,
}

const _liftDuration = Duration(milliseconds: 500);

const _liftToMenuDuration = Duration(milliseconds: 250);

const _liftToDragDuration = Duration(milliseconds: 200);
const _menuToDragDuration = Duration(milliseconds: 200);

const _liftDragThreshold = 20.0;
const _menuDragThreshold = 80.0;

class DragInteractionDrag implements SingleDrag {
  DragInteractionDrag({
    required this.delegate,
    required this.pointer,
    required this.initialOffset,
    required this.menuDragExtent,
    required this.initialMenuDragOffset,
  }) : _currentPosition = initialOffset {
    assert(!initialMenuDragOffset.isNaN);
    _ticker = Ticker((elapsed) {
      currentTime = elapsed;
      _onTick();
    });
    _ticker.start();
  }

  final int pointer;

  final ValueGetter<double> menuDragExtent;
  final double initialMenuDragOffset;

  final Offset initialOffset;
  Offset _currentPosition;

  late Duration currentTime;
  final startTime = const Duration(seconds: 0);
  final DragDelegate delegate;
  late Ticker _ticker;

  var _menuOverdrag = Offset.zero;

  SingleDragEndDetails? _dragEndDetails;

  // Gesture has ended
  bool get _ended => _dragEndDetails != null;

  _State _state = _State.none;

  Duration? _begin;
  Duration? _end;

  /// Lift factor saved when transitioning from menu to drag.
  double? _liftFactor;

  /// Menu factor saved when transitioning from menu to drag.
  double? _menuFactor;

  double _menuDragOffset = 0;

  double _maxDistance = 0;

  final _creationTime = Stopwatch()..start();

  void _updateDelegate({
    double? liftFactor,
    double? menuFactor,
    double? dragFactor,
  }) {
    assert(liftFactor == null || liftFactor <= 1.0);
    assert(menuFactor == null || menuFactor <= 1.0);
    assert(dragFactor == null || dragFactor <= 1.0);
    delegate.updateState(
      DragState(
        liftFactor: liftFactor ?? 0.0,
        menuFactor: menuFactor ?? 0.0,
        dragFactor: dragFactor ?? 0.0,
        menuOverdrag: _menuOverdrag,
        menuDragOffset: _menuDragOffset,
        globalPosition: _currentPosition,
      ),
    );
  }

  void _onTick() {
    if (_disposed) {
      return;
    }

    if (_state == _State.none) {
      if (delegate.hasMenu() && delegate.isMenuOpened()) {
        _state = _State.menu;
        _menuFactor = 1.0;
        _liftFactor = 1.0;
      } else {
        _state = _State.lifting;
        _begin = currentTime;
        _end = currentTime + _liftDuration;
      }
    }

    switch (_state) {
      case _State.lifting:
        return _onTickLifting();
      case _State.lifted:
        return _onTickLifted();
      case _State.liftedToMenu:
        return _onTickLiftedToMenu();
      case _State.menu:
        return _onTickMenu();
      case _State.toDrag:
        return _onTickToDrag();
      case _State.cancelLift:
        return _onTickCancelLift();
      case _State.waitingCancellationAfterDrag:
        break;
      case _State.none:
        throw StateError('Invalid state: $_state');
    }
  }

  Offset _dragOffsetToActualOffset(double offset) {
    return Offset(0, offset * menuDragExtent());
  }

  double get _distance => (_currentPosition -
          initialOffset +
          _dragOffsetToActualOffset(_menuDragOffset) -
          _dragOffsetToActualOffset(initialMenuDragOffset))
      .distance;

  bool _longPressRecognized = false;

  @override
  void longPressRecognized() {
    HapticFeedback.selectionClick();
    _longPressRecognized = true;
  }

  void _onTickLifting() {
    assert(_begin != null);
    final factor = _computeFactor(_begin!, _end!);

    if (_distance > _liftDragThreshold && delegate.canTransitionToDrag()) {
      if (!_longPressRecognized) {
        _transitionToCancelLift();
      } else {
        _transitionToDrag();
      }
    } else {
      if (factor >= 1.0) {
        _transitionToLifted();
      } else {
        _updateDelegate(liftFactor: factor);
      }
    }
  }

  void _onTickLifted() {
    if (delegate.hasMenu()) {
      _transitionToMenu();
    } else {
      if (_distance > _liftDragThreshold && delegate.canTransitionToDrag()) {
        _transitionToDrag();
      } else {
        _updateDelegate(liftFactor: 1.0);
      }
    }
  }

  // Reverses the timepoint so that at now it interpolates at (1.0 - current
  // factor) and at now + newDuration it interpolates at 1.0
  Duration _reverseTimepoint(
    Duration originalEnd,
    Duration originalDuration,
    Duration newDuration,
  ) {
    if (originalEnd <= currentTime) {
      return currentTime;
    } else {
      final factor =
          _computeFactor(originalEnd - originalDuration, originalEnd);
      return currentTime - newDuration * (1.0 - factor);
    }
  }

  void _transitionToLifted() {
    assert(_begin != null);
    _begin = null;
    _state = _State.lifted;
    _liftFactor = 1.0;
  }

  void _transitionToCancelLift() {
    _begin = _reverseTimepoint(
      _end ?? currentTime,
      _liftDuration,
      _liftDuration,
    );
    _end = _begin! + _liftDuration;
    _state = _State.cancelLift;
  }

  bool _disposed = false;

  void dispose() {
    assert(!_disposed);
    _disposed = true;
    _ticker.stop();
    _ticker.dispose();
  }

  void _onTickCancelLift() {
    assert(_begin != null);
    final factor = _computeFactor(_begin!, _end!);
    if (factor >= 1.0) {
      dispose();
      delegate.cancel();
    } else {
      _updateDelegate(liftFactor: 1.0 - factor);
    }
  }

  void _transitionToDrag() {
    if (_begin != null) {
      final currentFactor = _computeFactor(_begin!, _end!).clamp(0.0, 1.0);
      if (_liftFactor == null) {
        _liftFactor = currentFactor;
        // ignore: prefer_conditional_assignment
      } else if (_menuFactor == null) {
        _menuFactor = currentFactor;
      }
    }
    _begin = currentTime;
    if (_state == _State.menu) {
      _end = currentTime + _menuToDragDuration;
    } else {
      _end = currentTime + _liftToDragDuration;
    }
    if (_state == _State.menu) {
      HapticFeedback.selectionClick();
    }
    _state = _State.toDrag;
    delegate.beginTransitionToDrag();
  }

  void _transitionToMenu() {
    assert(_state == _State.lifted || _state == _State.lifting);
    delegate.beginTransitonToMenu();
    if (_state == _State.lifting) {
      _liftFactor = _computeFactor(_begin!, _end!);
    }
    _state = _State.liftedToMenu;
    _begin = currentTime;
    _end = currentTime + _liftToMenuDuration;
    _maxDistance = double.infinity;
  }

  void _onTickToDrag() {
    final dragFactor = _computeFactor(_begin!, _end!);
    if (dragFactor >= 1.0) {
      if (_ended) {
        delegate.cancel();
        dispose();
      } else {
        _updateDelegate(
          liftFactor: _liftFactor,
          menuFactor: _menuFactor,
          dragFactor: 1.0,
        );
        delegate.beginDrag(_currentPosition, pointer);
        _state = _State.waitingCancellationAfterDrag;
      }
    } else {
      _updateDelegate(
        liftFactor: _liftFactor,
        menuFactor: _menuFactor,
        dragFactor: dragFactor,
      );
    }
  }

  void _updateMenuOverdrag() {
    var menuDelta = _currentPosition -
        initialOffset -
        _dragOffsetToActualOffset(initialMenuDragOffset);

    if (menuDelta.dy < 0) {
      final menuDragExtent = this.menuDragExtent();
      final menuDragOffsetPixels = min(-menuDelta.dy, menuDragExtent);
      menuDelta = Offset(menuDelta.dx, menuDelta.dy + menuDragOffsetPixels);
      _menuDragOffset =
          menuDragExtent > 0 ? menuDragOffsetPixels / menuDragExtent : 0;
    } else {
      _menuDragOffset = 0;
    }
    _menuOverdrag = menuDelta;
  }

  void _onTickLiftedToMenu() {
    assert(_begin != null && _end != null);

    _updateMenuOverdrag();

    final menuFactor = _computeFactor(_begin!, _end!);
    double liftFactor = _liftFactor! + (1.0 - _liftFactor!) * menuFactor;

    if (menuFactor >= 1.0) {
      _menuFactor = 1.0;
      _liftFactor = 1.0;
      _state = _State.menu;
    } else {
      if (!_ended &&
          _distance > _liftDragThreshold &&
          delegate.canTransitionToDrag()) {
        _transitionToDrag();
      } else {
        _updateDelegate(
          liftFactor: liftFactor,
          menuFactor: menuFactor,
        );
      }
    }
  }

  void _onTickMenu() {
    _updateMenuOverdrag();
    _updateDelegate(
      menuFactor: 1.0,
      liftFactor: 1.0,
    );
    if (_ended) {
      delegate.menuDragEnded(_dragEndDetails?.velocity.pixelsPerSecond.dy ?? 0);
      dispose();
    } else if (_distance > _menuDragThreshold &&
        delegate.canTransitionToDrag()) {
      _transitionToDrag();
    }
  }

  double _computeFactor(Duration beginTime, Duration endTime) {
    final now = currentTime;
    final elapsed = now - beginTime;
    final duration = endTime - beginTime;
    final factor = elapsed.inMilliseconds / duration.inMilliseconds;
    return factor;
  }

  void _ensureDisposed() async {
    await Future.delayed(const Duration(milliseconds: 1000));

    /// This means we have a bug in the state machine.
    assert(_disposed, 'DragStateMachine was not disposed.');
    if (!_disposed) {
      dispose();
      delegate.cancel();
    }
  }

  @override
  void cancel() {
    if (_disposed) {
      return;
    }
    _ensureDisposed();

    if (_state == _State.toDrag) {
      delegate.didNotFinishTransitionToDrag();
    }
    dispose();
    if (_state != _State.waitingCancellationAfterDrag) {
      delegate.cancel();
    }
  }

  @override
  void end(SingleDragEndDetails details) {
    if (_disposed) {
      return;
    }
    _ensureDisposed();

    _dragEndDetails = details;

    // Detect tap up even when menu is opened. This is done here rather than
    // separate recognizer because we don't want the tap recognizer to comppete
    // with drag (which would cause drag slop delay).
    if (_maxDistance < 50 &&
        _state == _State.menu &&
        _creationTime.elapsed < const Duration(milliseconds: 350)) {
      dispose();
      delegate.onTapUp(_currentPosition);
      return;
    }

    switch (_state) {
      case _State.lifting:
        if (_longPressRecognized && delegate.hasMenu()) {
          _transitionToMenu();
        } else {
          _transitionToCancelLift();
        }
        break;
      case _State.lifted:
        _transitionToCancelLift();
        break;
      case _State.toDrag:
        delegate.didNotFinishTransitionToDrag();
        break;
      case _State.liftedToMenu:
      case _State.menu:
      case _State.cancelLift:
        // nothing to do here, let the animation finish
        break;
      case _State.waitingCancellationAfterDrag:
        // Starting drag should result in gesture being cancelled.
        // If the gesture ends instead it means user lifted finger before
        // drag started.
        delegate.didNotFinishTransitionToDrag();
        delegate.cancel();
        dispose();
        break;
      case _State.none:
        delegate.cancel();
        // Nothing has started yet
        dispose();
    }
  }

  @override
  void update(SingleDragUpdateDetails details) {
    if (_disposed) {
      return;
    }
    _currentPosition = details.globalPosition;
    _maxDistance =
        max(_maxDistance, (_currentPosition - initialOffset).distance);
  }
}

import '../gesture/single_drag.dart';

class DelayedDrag implements SingleDrag {
  DelayedDrag(Future<SingleDrag?> dragFuture) {
    _start(dragFuture);
  }

  void _start(Future<SingleDrag?> drag) async {
    _drag = await drag;
    if (_cancelled) {
      _drag?.cancel();
    } else {
      if (_longPressRecognized) {
        _drag?.longPressRecognized();
      }
      if (_endDetails != null) {
        _drag?.end(_endDetails!);
      }
    }
  }

  SingleDrag? _drag;
  bool _cancelled = false;
  SingleDragEndDetails? _endDetails;
  bool _longPressRecognized = false;

  @override
  void longPressRecognized() {
    _longPressRecognized = true;
    _drag?.longPressRecognized();
  }

  @override
  void cancel() {
    _cancelled = true;
    _drag?.cancel();
  }

  @override
  void end(SingleDragEndDetails details) {
    _drag?.end(details);
    _endDetails = details;
  }

  @override
  void update(SingleDragUpdateDetails details) {
    _drag?.update(details);
  }
}

import 'package:build_tool/src/rustup.dart';
import 'package:build_tool/src/util.dart';
import 'package:test/test.dart';

void main() {
  test('rustup with no toolchains', () {
    bool didListToolchains = false;
    bool didInstallStable = false;
    bool didListTargets = false;
    testRunCommandOverride = (args) {
      expect(args.executable, 'rustup');
      switch (args.arguments) {
        case ['toolchain', 'list']:
          didListToolchains = true;
          return TestRunCommandResult(stdout: 'no installed toolchains\n');
        case ['toolchain', 'install', 'stable']:
          didInstallStable = true;
          return TestRunCommandResult();
        case ['target', 'list', '--toolchain', 'stable', '--installed']:
          didListTargets = true;
          return TestRunCommandResult(
              stdout: 'x86_64-unknown-linux-gnu\nx86_64-apple-darwin\n');
        default:
          throw Exception('Unexpected call: ${args.arguments}');
      }
    };
    final rustup = Rustup();
    rustup.installToolchain('stable');
    expect(didInstallStable, true);
    expect(didListToolchains, true);
    expect(didListTargets, true);
    expect(rustup.installedTargets('stable'), [
      'x86_64-unknown-linux-gnu',
      'x86_64-apple-darwin',
    ]);
    testRunCommandOverride = null;
  });

  test('rustup with esp toolchain', () {
    final targetsQueried = <String>[];
    testRunCommandOverride = (args) {
      expect(args.executable, 'rustup');
      switch (args.arguments) {
        case ['toolchain', 'list']:
          return TestRunCommandResult(
              stdout: 'stable-aarch64-apple-darwin (default)\n'
                  'nightly-aarch64-apple-darwin\n'
                  'esp\n');
        case ['target', 'list', '--toolchain', String toolchain, '--installed']:
          targetsQueried.add(toolchain);
          return TestRunCommandResult(stdout: '$toolchain:target\n');
        default:
          throw Exception('Unexpected call: ${args.arguments}');
      }
    };
    final rustup = Rustup();
    expect(targetsQueried, [
      'stable-aarch64-apple-darwin',
      'nightly-aarch64-apple-darwin',
    ]);
    expect(rustup.installedTargets('stable'),
        ['stable-aarch64-apple-darwin:target']);
    expect(rustup.installedTargets('nightly'),
        ['nightly-aarch64-apple-darwin:target']);
  });
}

import 'package:build_tool/src/builder.dart';
import 'package:build_tool/src/options.dart';
import 'package:hex/hex.dart';
import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

void main() {
  test('parseCargoBuildOptions', () {
    final yaml = """
toolchain: nightly
extra_flags:
  - -Z
  # Comment here
  - build-std=panic_abort,std
""";
    final node = loadYamlNode(yaml);
    final options = CargoBuildOptions.parse(node);
    expect(options.toolchain, Toolchain.nightly);
    expect(options.flags, ['-Z', 'build-std=panic_abort,std']);
  });

  test('parsePrecompiledBinaries', () {
    final yaml = """
url_prefix: https://url-prefix
public_key: a4c3433798eb2c36edf2b94dbb4dd899d57496ca373a8982d8a792410b7f6445
""";
    final precompiledBinaries = PrecompiledBinaries.parse(loadYamlNode(yaml));
    final key = HEX.decode(
        'a4c3433798eb2c36edf2b94dbb4dd899d57496ca373a8982d8a792410b7f6445');
    expect(precompiledBinaries.uriPrefix, 'https://url-prefix');
    expect(precompiledBinaries.publicKey.bytes, key);
  });

  test('parseCargokitOptions', () {
    const yaml = '''
cargo:
  # For smalles binaries rebuilt the standard library with panic=abort
  debug:
    toolchain: nightly
    extra_flags:
      - -Z
      # Comment here
      - build-std=panic_abort,std
  release:
    toolchain: beta

precompiled_binaries:
  url_prefix: https://url-prefix
  public_key: a4c3433798eb2c36edf2b94dbb4dd899d57496ca373a8982d8a792410b7f6445
''';
    final options = CargokitCrateOptions.parse(loadYamlNode(yaml));
    expect(options.precompiledBinaries?.uriPrefix, 'https://url-prefix');
    final key = HEX.decode(
        'a4c3433798eb2c36edf2b94dbb4dd899d57496ca373a8982d8a792410b7f6445');
    expect(options.precompiledBinaries?.publicKey.bytes, key);

    final debugOptions = options.cargo[BuildConfiguration.debug]!;
    expect(debugOptions.toolchain, Toolchain.nightly);
    expect(debugOptions.flags, ['-Z', 'build-std=panic_abort,std']);

    final releaseOptions = options.cargo[BuildConfiguration.release]!;
    expect(releaseOptions.toolchain, Toolchain.beta);
    expect(releaseOptions.flags, []);
  });

  test('parseCargokitUserOptions', () {
    const yaml = '''
use_precompiled_binaries: false
verbose_logging: true
''';
    final options = CargokitUserOptions.parse(loadYamlNode(yaml));
    expect(options.usePrecompiledBinaries, false);
    expect(options.verboseLogging, true);
  });
}

import 'package:build_tool/src/builder.dart';
import 'package:test/test.dart';

void main() {
  test('parseBuildConfiguration', () {
    var b = BuildEnvironment.parseBuildConfiguration('debug');
    expect(b, BuildConfiguration.debug);

    b = BuildEnvironment.parseBuildConfiguration('profile');
    expect(b, BuildConfiguration.profile);

    b = BuildEnvironment.parseBuildConfiguration('release');
    expect(b, BuildConfiguration.release);

    b = BuildEnvironment.parseBuildConfiguration('debug-dev');
    expect(b, BuildConfiguration.debug);

    b = BuildEnvironment.parseBuildConfiguration('profile');
    expect(b, BuildConfiguration.profile);

    b = BuildEnvironment.parseBuildConfiguration('profile-prod');
    expect(b, BuildConfiguration.profile);

    // fallback to release
    b = BuildEnvironment.parseBuildConfiguration('unknown');
    expect(b, BuildConfiguration.release);
  });
}

#ifndef RUNNER_WIN32_WINDOW_H_
#define RUNNER_WIN32_WINDOW_H_

#include <windows.h>

#include <functional>
#include <memory>
#include <string>

// A class abstraction for a high DPI-aware Win32 Window. Intended to be
// inherited from by classes that wish to specialize with custom
// rendering and input handling
class Win32Window {
public:
  struct Point {
    unsigned int x;
    unsigned int y;
    Point(unsigned int x, unsigned int y) : x(x), y(y) {}
  };

  struct Size {
    unsigned int width;
    unsigned int height;
    Size(unsigned int width, unsigned int height)
        : width(width), height(height) {}
  };

  Win32Window();
  virtual ~Win32Window();

  // Creates and shows a win32 window with |title| and position and size using
  // |origin| and |size|. New windows are created on the default monitor. Window
  // sizes are specified to the OS in physical pixels, hence to ensure a
  // consistent size to will treat the width height passed in to this function
  // as logical pixels and scale to appropriate for the default monitor. Returns
  // true if the window was created successfully.
  bool CreateAndShow(const std::wstring &title, const Point &origin,
                     const Size &size);

  // Release OS resources associated with window.
  void Destroy();

  // Inserts |content| into the window tree.
  void SetChildContent(HWND content);

  // Returns the backing Window handle to enable clients to set icon and other
  // window properties. Returns nullptr if the window has been destroyed.
  HWND GetHandle();

  // If true, closing this window will quit the application.
  void SetQuitOnClose(bool quit_on_close);

  // Return a RECT representing the bounds of the current client area.
  RECT GetClientArea();

protected:
  // Processes and route salient window messages for mouse handling,
  // size change and DPI. Delegates handling of these to member overloads that
  // inheriting classes can handle.
  virtual LRESULT MessageHandler(HWND window, UINT const message,
                                 WPARAM const wparam,
                                 LPARAM const lparam) noexcept;

  // Called when CreateAndShow is called, allowing subclass window-related
  // setup. Subclasses should return false if setup fails.
  virtual bool OnCreate();

  // Called when Destroy is called.
  virtual void OnDestroy();

private:
  friend class WindowClassRegistrar;

  // OS callback called by message pump. Handles the WM_NCCREATE message which
  // is passed when the non-client area is being created and enables automatic
  // non-client DPI scaling so that the non-client area automatically
  // responsponds to changes in DPI. All other messages are handled by
  // MessageHandler.
  static LRESULT CALLBACK WndProc(HWND const window, UINT const message,
                                  WPARAM const wparam,
                                  LPARAM const lparam) noexcept;

  // Retrieves a class instance pointer for |window|
  static Win32Window *GetThisFromHandle(HWND const window) noexcept;

  bool quit_on_close_ = false;

  // window handle for top level window.
  HWND window_handle_ = nullptr;

  // window handle for hosted content.
  HWND child_content_ = nullptr;
};

#endif // RUNNER_WIN32_WINDOW_H_

#include "win32_window.h"

#include <flutter_windows.h>

#include "resource.h"

namespace {

constexpr const wchar_t kWindowClassName[] = L"FLUTTER_RUNNER_WIN32_WINDOW";

// The number of Win32Window objects that currently exist.
static int g_active_window_count = 0;

using EnableNonClientDpiScaling = BOOL __stdcall(HWND hwnd);

// Scale helper to convert logical scaler values to physical using passed in
// scale factor
int Scale(int source, double scale_factor) {
  return static_cast<int>(source * scale_factor);
}

// Dynamically loads the |EnableNonClientDpiScaling| from the User32 module.
// This API is only needed for PerMonitor V1 awareness mode.
void EnableFullDpiSupportIfAvailable(HWND hwnd) {
  HMODULE user32_module = LoadLibraryA("User32.dll");
  if (!user32_module) {
    return;
  }
  auto enable_non_client_dpi_scaling =
      reinterpret_cast<EnableNonClientDpiScaling *>(
          GetProcAddress(user32_module, "EnableNonClientDpiScaling"));
  if (enable_non_client_dpi_scaling != nullptr) {
    enable_non_client_dpi_scaling(hwnd);
    FreeLibrary(user32_module);
  }
}

} // namespace

// Manages the Win32Window's window class registration.
class WindowClassRegistrar {
public:
  ~WindowClassRegistrar() = default;

  // Returns the singleton registar instance.
  static WindowClassRegistrar *GetInstance() {
    if (!instance_) {
      instance_ = new WindowClassRegistrar();
    }
    return instance_;
  }

  // Returns the name of the window class, registering the class if it hasn't
  // previously been registered.
  const wchar_t *GetWindowClass();

  // Unregisters the window class. Should only be called if there are no
  // instances of the window.
  void UnregisterWindowClass();

private:
  WindowClassRegistrar() = default;

  static WindowClassRegistrar *instance_;

  bool class_registered_ = false;
};

WindowClassRegistrar *WindowClassRegistrar::instance_ = nullptr;

const wchar_t *WindowClassRegistrar::GetWindowClass() {
  if (!class_registered_) {
    WNDCLASS window_class{};
    window_class.hCursor = LoadCursor(nullptr, IDC_ARROW);
    window_class.lpszClassName = kWindowClassName;
    window_class.style = CS_HREDRAW | CS_VREDRAW;
    window_class.cbClsExtra = 0;
    window_class.cbWndExtra = 0;
    window_class.hInstance = GetModuleHandle(nullptr);
    window_class.hIcon =
        LoadIcon(window_class.hInstance, MAKEINTRESOURCE(IDI_APP_ICON));
    window_class.hbrBackground = 0;
    window_class.lpszMenuName = nullptr;
    window_class.lpfnWndProc = Win32Window::WndProc;
    RegisterClass(&window_class);
    class_registered_ = true;
  }
  return kWindowClassName;
}

void WindowClassRegistrar::UnregisterWindowClass() {
  UnregisterClass(kWindowClassName, nullptr);
  class_registered_ = false;
}

Win32Window::Win32Window() { ++g_active_window_count; }

Win32Window::~Win32Window() {
  --g_active_window_count;
  Destroy();
}

bool Win32Window::CreateAndShow(const std::wstring &title, const Point &origin,
                                const Size &size) {
  Destroy();

  const wchar_t *window_class =
      WindowClassRegistrar::GetInstance()->GetWindowClass();

  const POINT target_point = {static_cast<LONG>(origin.x),
                              static_cast<LONG>(origin.y)};
  HMONITOR monitor = MonitorFromPoint(target_point, MONITOR_DEFAULTTONEAREST);
  UINT dpi = FlutterDesktopGetDpiForMonitor(monitor);
  double scale_factor = dpi / 96.0;

  HWND window = CreateWindow(
      window_class, title.c_str(), WS_OVERLAPPEDWINDOW | WS_VISIBLE,
      Scale(origin.x, scale_factor), Scale(origin.y, scale_factor),
      Scale(size.width, scale_factor), Scale(size.height, scale_factor),
      nullptr, nullptr, GetModuleHandle(nullptr), this);

  if (!window) {
    return false;
  }

  return OnCreate();
}

// static
LRESULT CALLBACK Win32Window::WndProc(HWND const window, UINT const message,
                                      WPARAM const wparam,
                                      LPARAM const lparam) noexcept {
  if (message == WM_NCCREATE) {
    auto window_struct = reinterpret_cast<CREATESTRUCT *>(lparam);
    SetWindowLongPtr(window, GWLP_USERDATA,
                     reinterpret_cast<LONG_PTR>(window_struct->lpCreateParams));

    auto that = static_cast<Win32Window *>(window_struct->lpCreateParams);
    EnableFullDpiSupportIfAvailable(window);
    that->window_handle_ = window;
  } else if (Win32Window *that = GetThisFromHandle(window)) {
    return that->MessageHandler(window, message, wparam, lparam);
  }

  return DefWindowProc(window, message, wparam, lparam);
}

LRESULT
Win32Window::MessageHandler(HWND hwnd, UINT const message, WPARAM const wparam,
                            LPARAM const lparam) noexcept {
  switch (message) {
  case WM_DESTROY:
    window_handle_ = nullptr;
    Destroy();
    if (quit_on_close_) {
      PostQuitMessage(0);
    }
    return 0;

  case WM_DPICHANGED: {
    auto newRectSize = reinterpret_cast<RECT *>(lparam);
    LONG newWidth = newRectSize->right - newRectSize->left;
    LONG newHeight = newRectSize->bottom - newRectSize->top;

    SetWindowPos(hwnd, nullptr, newRectSize->left, newRectSize->top, newWidth,
                 newHeight, SWP_NOZORDER | SWP_NOACTIVATE);

    return 0;
  }
  case WM_SIZE: {
    RECT rect = GetClientArea();
    if (child_content_ != nullptr) {
      // Size and position the child window.
      MoveWindow(child_content_, rect.left, rect.top, rect.right - rect.left,
                 rect.bottom - rect.top, TRUE);
    }
    return 0;
  }

  case WM_ACTIVATE:
    if (child_content_ != nullptr) {
      SetFocus(child_content_);
    }
    return 0;
  }

  return DefWindowProc(window_handle_, message, wparam, lparam);
}

void Win32Window::Destroy() {
  OnDestroy();

  if (window_handle_) {
    DestroyWindow(window_handle_);
    window_handle_ = nullptr;
  }
  if (g_active_window_count == 0) {
    WindowClassRegistrar::GetInstance()->UnregisterWindowClass();
  }
}

Win32Window *Win32Window::GetThisFromHandle(HWND const window) noexcept {
  return reinterpret_cast<Win32Window *>(
      GetWindowLongPtr(window, GWLP_USERDATA));
}

void Win32Window::SetChildContent(HWND content) {
  child_content_ = content;
  SetParent(content, window_handle_);
  RECT frame = GetClientArea();

  MoveWindow(content, frame.left, frame.top, frame.right - frame.left,
             frame.bottom - frame.top, true);

  SetFocus(child_content_);
}

RECT Win32Window::GetClientArea() {
  RECT frame;
  GetClientRect(window_handle_, &frame);
  return frame;
}

HWND Win32Window::GetHandle() { return window_handle_; }

void Win32Window::SetQuitOnClose(bool quit_on_close) {
  quit_on_close_ = quit_on_close;
}

bool Win32Window::OnCreate() {
  // No-op; provided for subclasses.
  return true;
}

void Win32Window::OnDestroy() {
  // No-op; provided for subclasses.
}

