  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is JSValue &&
          runtimeType == other.runtimeType &&
          JSValueRef.jSValueIsStrictEqual(
                  context.pointer, pointer, other.pointer) ==
              1;

