impl PlatformMenuContextDelegate for MenuManager {
    fn on_show_menu(&self, context_id: PlatformMenuContextId, menu_configuration_id: i64) {
        self.invoker
            .call_method_sync(context_id, "onShowMenu", menu_configuration_id, |r| {
                r.ok_log();
            });
    }

    fn on_hide_menu(
        &self,
        context_id: PlatformMenuContextId,
        menu_configuration_id: i64,
        item_selected: bool,
    ) {
        #[derive(IntoValue)]
        #[irondash(rename_all = "camelCase")]
        struct HideMenuRequest {
            menu_configuration_id: i64,
            item_selected: bool,
        }
        self.invoker.call_method_sync(
            context_id,
            "onHideMenu",
            HideMenuRequest {
                menu_configuration_id,
                item_selected,
            },
            |r| {
                r.ok_log();
            },
        );
    }

    fn on_preview_action(&self, context_id: PlatformMenuContextId, menu_configuration_id: i64) {
        self.invoker
            .call_method_sync(context_id, "onPreviewAction", menu_configuration_id, |r| {
                r.ok_log();
            });
    }

    fn get_platform_drag_contexts(&self) -> Vec<Rc<PlatformDragContext>> {
        Context::get().drag_manager().get_platform_drag_contexts()
    }

    fn get_menu_configuration_for_location(
        &self,
        context_id: PlatformMenuContextId,
        location: Point,
    ) -> Arc<Promise<PromiseResult<MenuConfiguration>>> {
        let res = Arc::new(Promise::new());
        let res_clone = res.clone();
        let weak_self = self.weak_self.clone();
        spawn(async move {
            let this = weak_self.upgrade();
            if let Some(this) = this {
                match this
                    .get_menu_configuration_for_location(context_id, location)
                    .await
                    .ok_log_unexpected()
                    .flatten()
                {
                    Some(data) => {
                        res_clone.set(PromiseResult::Ok { value: data });
                    }
                    None => {
                        res_clone.set(PromiseResult::Cancelled);
                    }
                }
            } else {
                res_clone.set(PromiseResult::Cancelled);
            }
        });
        res
    }

    fn send_writing_tools_replacement(
        &self,
        context_id: PlatformMenuContextId,
        request: WritingToolsReplacementRequest,
    ) {
        self.invoker
            .call_method_sync(context_id, "sendWritingToolsReplacement", request, |r| {
                r.ok_log();
            });
    }
}

#[async_trait(?Send)]
impl AsyncMethodHandler for MenuManager {
    fn assign_weak_self(&self, weak_self: Weak<Self>) {
        self.weak_self.set(weak_self);
    }

    fn assign_invoker(&self, invoker: AsyncMethodInvoker) {
        self.invoker.set(invoker);
    }

    async fn on_method_call(&self, call: MethodCall) -> PlatformResult {
        match call.method.as_str() {
            "newContext" => {
                self.new_context(call.isolate, call.args.try_into()?)?;
                Ok(Value::Null)
            }
            "registerMenu" => {
                let id = self
                    .register_menu(call.args.try_into()?, call.isolate)
                    .await?;
                Ok(id.into())
            }
            "disposeMenu" => {
                self.dispose_menu(call.args.try_into()?).await?;
                Ok(Value::Null)
            }
            "updatePreviewImage" => {
                self.update_preview_image(call.args.try_into()?, call.isolate)?;
                Ok(Value::Null)
            }
            "showContextMenu" => {
                let res = self
                    .show_context_menu(call.args.try_into()?, call.isolate)
                    .await?;
                Ok(res.into())
            }
            _ => Ok(Value::Null),
        }
    }
}

use std::{fmt::Display, panic::Location};

use irondash_message_channel::{MethodCallError, SendMessageError};
use log::{Level, Record};

use crate::error::NativeExtensionsError;

fn log_error<E: Display>(err: E, location: &Location) {
    log::logger().log(
        &Record::builder()
            .args(format_args!("Unexpected error {err} at {location}"))
            .file(Some(location.file()))
            .line(Some(location.line()))
            .level(Level::Error)
            .build(),
    );
}

pub trait OkLog<T> {
    fn ok_log(self) -> Option<T>;
}

impl<T, E> OkLog<T> for std::result::Result<T, E>
where
    E: Display,
{
    #[track_caller]
    fn ok_log(self) -> Option<T> {
        match self {
            Ok(value) => Some(value),
            Err(err) => {
                let location = Location::caller();
                log_error(err, location);
                None
            }
        }
    }
}

pub trait OkLogUnexpected<T> {
    fn ok_log_unexpected(self) -> Option<T>;
}

impl<T> OkLogUnexpected<T> for std::result::Result<T, NativeExtensionsError> {
    #[track_caller]
    fn ok_log_unexpected(self) -> Option<T> {
        match self {
            Ok(value) => Some(value),
            Err(err) => {
                if let NativeExtensionsError::MethodCallError(
                    MethodCallError::SendError(err), //
                ) = &err
                {
                    match err {
                        // These are expected errors during isolate shutdown and
                        // do not need to be logged
                        SendMessageError::MessageRefused => return None,
                        SendMessageError::IsolateShutDown => return None,
                        _ => {}
                    }
                }
                let location = Location::caller();
                log_error(err, location);
                None
            }
        }
    }
}

