// There is a separate $DataReaderHandle and $DataReaderItemHandle definition for
// web and native. The typedef with $prefix is used within the web/native section
// so that dart analyzer can find the correct type.
typedef DataReaderHandle = $DataReaderHandle;
typedef DataReaderItemHandle = $DataReaderItemHandle;

abstract class ReaderManager {
  static final ReaderManager instance = ReaderManagerImpl();

  Future<void> dispose(DataReaderHandle reader);

  Future<List<DataReaderItemHandle>> getItems(DataReaderHandle reader);

  Future<List<String>> getItemFormats(DataReaderItemHandle handle);

  (Future<Object?>, ReadProgress) getItemData(
    DataReaderItemHandle handle, {
    required String format,
  });

  /// Loads as many item infos as possible within the given timeout.
  Future<List<DataReaderItemInfo>> getItemInfo(
    Iterable<DataReaderItemHandle> handles, {
    Duration? timeout,
  });

  VirtualFile createVirtualFileFromUri(Uri uri);
}

import 'dart:async';

import 'package:flutter/foundation.dart';

import 'mutex.dart';
import 'reader_manager.dart';

class DataReader {
  Future<List<DataReaderItem>> getItems() {
    return _mutex.protect(() async {
      _items ??= (await ReaderManager.instance.getItems(_handle))
          .map((handle) => DataReaderItem(handle: handle))
          .toList(growable: false);
      return _items!;
    });
  }

  DataReader({
    required DataReaderHandle handle,
  }) : _handle = handle;

  Future<void> dispose() => ReaderManager.instance.dispose(_handle);

  final _mutex = Mutex();

  final DataReaderHandle _handle;
  List<DataReaderItem>? _items;
}

/// Progress of a read operation.
abstract class ReadProgress {
  /// Range is 0.0 to 1.0.
  /// Starts with null (indeterminate progress).
  /// Guaranteed to fire at least once on either completion or failure
  /// (with value of 1.0).
  ValueListenable<double?> get fraction;

  /// This may change over time, client must be prepared to handle that.
  ValueListenable<bool> get cancellable;

  /// Cancels the read operation. Does nothing if already cancelled or not
  /// cancellable.
  void cancel();
}

class DataReaderItemInfo {
  DataReaderItemInfo(
    this._handle, {
    required this.formats,
    required this.synthesizedFormats,
    required this.virtualReceivers,
    required this.suggestedName,
    required this.synthesizedFromURIFormat,
  });

  DataReaderItem get item => DataReaderItem(handle: _handle);
  final List<String> formats;
  final List<String> synthesizedFormats;
  final List<VirtualFileReceiver> virtualReceivers;
  final String? suggestedName;
  final String? synthesizedFromURIFormat;
  final DataReaderItemHandle _handle;
}

class DataReaderItem {
  Future<List<String>> getAvailableFormats() {
    return _mutex.protect(() async {
      _availableFormats ??=
          await ReaderManager.instance.getItemFormats(_handle);
      return _availableFormats!;
    });
  }

  (Future<Object?>, ReadProgress) getDataForFormat(
    String format,
  ) {
    return ReaderManager.instance.getItemData(_handle, format: format);
  }

  static Future<List<DataReaderItemInfo>> getItemInfo(
    Iterable<DataReaderItem> items, {
    Duration? timeout,
  }) {
    return ReaderManager.instance.getItemInfo(
      items.map(
        (e) => e._handle,
      ),
      timeout: timeout,
    );
  }

  DataReaderItemInfo? __itemInfo;

  Future<DataReaderItemInfo> _getItemInfo() async {
    if (__itemInfo == null) {
      final info = await ReaderManager.instance.getItemInfo([_handle]);
      __itemInfo = info[0];
    }
    return __itemInfo!;
  }

  Future<bool> isSynthesized(String format) async {
    return (await _getItemInfo()).synthesizedFormats.contains(format);
  }

  /// When `true` the content can be received through [getVirtualFileReceiver].
  /// On macOS and Windows if [isVirtual] is `true` the content can only be
  /// received through [getVirtualFileReceiver] - [getDataForFormat] will return
  /// `null`.
  Future<bool> isVirtual(String format) async {
    return (await _getItemInfo())
        .virtualReceivers
        .any((element) => element.format == format);
  }

  Future<String?> getSuggestedName() async {
    return (await _getItemInfo()).suggestedName;
  }

  @override
  bool operator ==(Object other) {
    return other is DataReaderItem && other._handle == _handle;
  }

  @override
  int get hashCode => _handle.hashCode;

  DataReaderItem({
    required DataReaderItemHandle handle,
  }) : _handle = handle;

  final DataReaderItemHandle _handle;

  final _mutex = Mutex();
  List<String>? _availableFormats;
}

