      result(isMuted)
    case MethodName.setMute:
      let arg = call.arguments as? [String: Any]
      let isMute = arg?[MethodArgument.isMute] as? Bool

      volumeController.setMute(isMute: isMute!)
      result(nil)
    default:
      result(FlutterMethodNotImplemented)
    }
  }
}

