#ifndef FLUTTER_PLUGIN_VOLUME_CONTROLLER_PLUGIN_H_
#define FLUTTER_PLUGIN_VOLUME_CONTROLLER_PLUGIN_H_

#include <flutter/method_channel.h>
#include <flutter/plugin_registrar_windows.h>

#include <memory>

#include "include/volume_controller/constants.h"
#include "include/volume_controller/volume_controller.h"
#include "include/volume_controller/volume_listener.h"
#include "include/volume_controller/volume_stream_handler.h"
#include "include/volume_controller/helper.h"

namespace volume_controller
{
    class VolumeControllerPlugin : public flutter::Plugin
    {
    public:
        static void RegisterWithRegistrar(flutter::PluginRegistrarWindows *registrar);

        VolumeControllerPlugin();
        virtual ~VolumeControllerPlugin();

        // Disallow copy and assign.
        VolumeControllerPlugin(const VolumeControllerPlugin &) = delete;
        VolumeControllerPlugin &operator=(const VolumeControllerPlugin &) = delete;

        // Called when a method is called on this plugin's channel from Dart.
        void HandleMethodCall(
            const flutter::MethodCall<flutter::EncodableValue> &method_call,
            std::unique_ptr<flutter::MethodResult<flutter::EncodableValue>> result);

    private:
        volume_controller::VolumeController &volume_controller_;
    };

} // namespace volume_controller

#endif // FLUTTER_PLUGIN_VOLUME_CONTROLLER_PLUGIN_H_

#include "volume_controller_plugin.h"

// This must be included before many other Windows headers.
#include <windows.h>

#include <flutter/method_channel.h>
#include <flutter/event_channel.h>
#include <flutter/plugin_registrar_windows.h>
#include <flutter/standard_method_codec.h>
#include <memory>
#include <sstream>

namespace volume_controller
{
  VolumeControllerPlugin::VolumeControllerPlugin() : volume_controller_(VolumeController::GetInstance())
  {
    volume_controller_.Initialize();
  }

  VolumeControllerPlugin::~VolumeControllerPlugin()
  {
    volume_controller_.Dispose();
  }

  // static
  void VolumeControllerPlugin::RegisterWithRegistrar(
      flutter::PluginRegistrarWindows *registrar)
  {
    auto plugin = std::make_unique<VolumeControllerPlugin>();

    auto method_channel =
        std::make_unique<flutter::MethodChannel<flutter::EncodableValue>>(
            registrar->messenger(), constants::ChannelName::methodChannel,
            &flutter::StandardMethodCodec::GetInstance());

    auto event_channel =
        std::make_unique<flutter::EventChannel<flutter::EncodableValue>>(
            registrar->messenger(), constants::ChannelName::eventChannel,
            &flutter::StandardMethodCodec::GetInstance());

    // Register the method channel
    method_channel->SetMethodCallHandler(
        [plugin_pointer = plugin.get()](const auto &call, auto result)
        {
          plugin_pointer->HandleMethodCall(call, std::move(result));
        });

    // Register the event channel
    event_channel->SetStreamHandler(std::make_unique<volume_stream_handler::VolumeStreamHandler>());

    // Set the channel to the plugin
    registrar->AddPlugin(std::move(plugin));
  }

  void VolumeControllerPlugin::HandleMethodCall(
      const flutter::MethodCall<flutter::EncodableValue> &method_call,
      std::unique_ptr<flutter::MethodResult<flutter::EncodableValue>> result)
  {
    const std::string &method_name = method_call.method_name();

    if (method_name == constants::MethodName::getVolume)
    {
      result->Success(flutter::EncodableValue(volume_controller_.GetVolume()));
    }
    else if (method_name == constants::MethodName::setVolume)
    {
      const auto *arguments = std::get_if<flutter::EncodableMap>(method_call.arguments());
      const double *volume = std::get_if<double>(GetArgValue(*arguments, constants::MethodArgument::volume));

      if (!volume)
      {
        result->Error("InvalidArguments", "Volume argument is missing");
        return;
      }

      // Set the volume
      bool success = volume_controller_.SetVolume(static_cast<float>(*volume));
      if (!success)
      {
        result->Error("SetVolumeError", "Failed to set volume");
        return;
      }

      result->Success();
    }
    else if (method_name == constants::MethodName::isMuted)
    {
      result->Success(flutter::EncodableValue(volume_controller_.IsMuted()));
    }
    else if (method_call.method_name().compare(constants::MethodName::setMute) == 0)
    {
      const auto *arguments = std::get_if<flutter::EncodableMap>(method_call.arguments());
      const bool *isMute = std::get_if<bool>(GetArgValue(*arguments, constants::MethodArgument::isMute));

      if (!isMute)
      {
        result->Error("InvalidArguments", "isMute argument is missing");
        return;
      }

      // Set the mute
      bool success = volume_controller_.SetMute(*isMute);
      if (!success)
      {
        result->Error("SetMuteError", "Failed to set mute");
        return;
      }

      result->Success();
    }
    else
    {
      result->NotImplemented();
    }
  }

} // namespace volume_controller

#include "include/volume_controller/volume_controller_plugin.h"
#include "include/volume_controller/constants.h"
#include "include/volume_controller/volume_controller.h"
#include "include/volume_controller/audio_controller.h"

#include <flutter_linux/flutter_linux.h>
#include <gtk/gtk.h>
#include <alsa/asoundlib.h>

#include <cstring>

#define VOLUME_CONTROLLER_PLUGIN(obj)                                     \
  (G_TYPE_CHECK_INSTANCE_CAST((obj), volume_controller_plugin_get_type(), \
                              VolumeControllerPlugin))

struct _VolumeControllerPlugin
{
  GObject parent_instance;

  AudioController *audioController;

  FlEventChannel *event_channel = NULL;
};

G_DEFINE_TYPE(VolumeControllerPlugin, volume_controller_plugin, g_object_get_type())

static void on_volume_changed_callback(double new_volume, gpointer user_data)
{
  VolumeControllerPlugin *plugin = VOLUME_CONTROLLER_PLUGIN(user_data);

  if (plugin && plugin->event_channel)
  {
    fl_event_channel_send(plugin->event_channel, fl_value_new_float(new_volume), NULL, NULL);
  }
}

// Called when a method call is received from Flutter.
static void volume_controller_plugin_handle_method_call(
    VolumeControllerPlugin *self,
    FlMethodCall *method_call)
{
  g_autoptr(FlMethodResponse) response = nullptr;

  const gchar *method = fl_method_call_get_name(method_call);
  FlValue *args = fl_method_call_get_args(method_call);

  if (strcmp(method, MethodName::getVolume) == 0)
  {
    response = get_volume(self->audioController);
  }
  else if (strcmp(method, MethodName::setVolume) == 0)
  {
    FlValue *arg = fl_value_lookup_string(args, MethodArgument::volume);
    double volume = fl_value_get_float(arg);

    response = set_volume(self->audioController, volume);
  }
  else if (strcmp(method, MethodName::isMuted) == 0)
  {
    response = is_muted(self->audioController);
  }
  else if (strcmp(method, MethodName::setMute) == 0)
  {
    FlValue *arg = fl_value_lookup_string(args, MethodArgument::isMute);
    bool mute = fl_value_get_bool(arg);
    response = set_mute(self->audioController, mute);
  }
  else
  {
    response = FL_METHOD_RESPONSE(fl_method_not_implemented_response_new());
  }

  fl_method_call_respond(method_call, response, nullptr);
}

static FlMethodErrorResponse *event_listen_cb(FlEventChannel *channel, FlValue *args, gpointer user_data)
{
  VolumeControllerPlugin *self = VOLUME_CONTROLLER_PLUGIN(user_data);

  if (!self || !self->audioController)
  {
    return FL_METHOD_ERROR_RESPONSE(fl_method_error_response_new("PluginError", "AudioController not initialized.", nullptr));
  }

  if (args && fl_value_get_type(args) == FL_VALUE_TYPE_MAP)
  {
    FlValue *fetch_arg = fl_value_lookup_string(args, EventArgument::fetchInitialVolume);
    if (fetch_arg && fl_value_get_type(fetch_arg) == FL_VALUE_TYPE_BOOL)
    {
      self->audioController->fetch_initial_volume = fl_value_get_bool(fetch_arg);
    }
  }

  if (!self->audioController->start_listening_for_volume_changes(on_volume_changed_callback, self))
  {
    return FL_METHOD_ERROR_RESPONSE(fl_method_error_response_new("AudioError", "Failed to start volume listener.", nullptr));
  }

  return NULL;
}

static FlMethodErrorResponse *event_cancel_cb(FlEventChannel *channel, FlValue *args, gpointer user_data)
{
  VolumeControllerPlugin *self = VOLUME_CONTROLLER_PLUGIN(user_data);

  if (!self || !self->audioController)
  {
    return NULL;
  }

  self->audioController->stop_listening_for_volume_changes();

  return NULL;
}

static void volume_controller_plugin_init(VolumeControllerPlugin *self)
{
  try
  {
    self->audioController = new AudioController();
  }
  catch (const std::exception &e)
  {
    g_critical("Failed to create AudioController: %s", e.what());
    self->audioController = nullptr;
  }
}

static void volume_controller_plugin_dispose(GObject *object)
{
  VolumeControllerPlugin *self = VOLUME_CONTROLLER_PLUGIN(object);

  g_object_unref(self->event_channel);

  if (self->audioController)
  {
    delete self->audioController;
    self->audioController = nullptr;
  }

  G_OBJECT_CLASS(volume_controller_plugin_parent_class)->dispose(object);
}

static void volume_controller_plugin_class_init(VolumeControllerPluginClass *klass)
{
  G_OBJECT_CLASS(klass)->dispose = volume_controller_plugin_dispose;
}

static void method_call_cb(FlMethodChannel *channel, FlMethodCall *method_call,
                           gpointer user_data)
{
  VolumeControllerPlugin *plugin = VOLUME_CONTROLLER_PLUGIN(user_data);
  volume_controller_plugin_handle_method_call(plugin, method_call);
}

void volume_controller_plugin_register_with_registrar(FlPluginRegistrar *registrar)
{
  VolumeControllerPlugin *plugin = VOLUME_CONTROLLER_PLUGIN(
      g_object_new(volume_controller_plugin_get_type(), nullptr));

  g_autoptr(FlStandardMethodCodec) codec = fl_standard_method_codec_new();
  g_autoptr(FlMethodChannel) channel =
      fl_method_channel_new(fl_plugin_registrar_get_messenger(registrar),
                            ChannelName::methodChannel,
                            FL_METHOD_CODEC(codec));
  fl_method_channel_set_method_call_handler(channel, method_call_cb,
                                            g_object_ref(plugin),
                                            g_object_unref);

  // Register event channel with correct handler signatures
  plugin->event_channel = fl_event_channel_new(
      fl_plugin_registrar_get_messenger(registrar),
      ChannelName::eventChannel,
      FL_METHOD_CODEC(codec));
  fl_event_channel_set_stream_handlers(plugin->event_channel,
                                       event_listen_cb,
                                       event_cancel_cb,
                                       g_object_ref(plugin),
                                       g_object_unref);

  g_object_unref(plugin);
}

#include "include/volume_controller/audio_controller.h"

#include <flutter_linux/flutter_linux.h>

FlMethodResponse *get_volume(AudioController *controller)
{
    try
    {
        double volume = controller->get_volume();
        g_autoptr(FlValue) result = fl_value_new_float(volume);
        return FL_METHOD_RESPONSE(fl_method_success_response_new(result));
    }
    catch (const std::exception &e)
    {
        return FL_METHOD_RESPONSE(fl_method_error_response_new("Error", e.what(), NULL));
    }
}

FlMethodResponse *set_volume(AudioController *controller, double volume)
{
    try
    {
        if (volume < 0.0 || volume > 1.0)
        {
            return FL_METHOD_RESPONSE(fl_method_error_response_new("InvalidArgument", "Volume must be between 0 and 1", NULL));
        }
        controller->set_volume(volume);
        return FL_METHOD_RESPONSE(fl_method_success_response_new(NULL));
    }
    catch (const std::exception &e)
    {
        return FL_METHOD_RESPONSE(fl_method_error_response_new("Error", e.what(), NULL));
    }
}

FlMethodResponse *is_muted(AudioController *controller)
{
    try
    {
        bool muted = controller->is_muted();
        g_autoptr(FlValue) result = fl_value_new_bool(muted);
        return FL_METHOD_RESPONSE(fl_method_success_response_new(result));
    }
    catch (const std::exception &e)
    {
        return FL_METHOD_RESPONSE(fl_method_error_response_new("Error", e.what(), NULL));
    }
}

FlMethodResponse *set_mute(AudioController *controller, bool mute)
{
    try
    {
        controller->set_mute(mute);
        return FL_METHOD_RESPONSE(fl_method_success_response_new(NULL));
    }
    catch (const std::exception &e)
    {
        return FL_METHOD_RESPONSE(fl_method_error_response_new("Error", e.what(), NULL));
    }
}

#include "include/volume_controller/audio_controller.h"
#include <iostream>
#include <chrono>
#include <thread>

AudioController::AudioController()
    : cardName_("default")
{
    open_mixer();
}

AudioController::AudioController(const std::string cardName)
    : cardName_(cardName)
{
    open_mixer();
}

AudioController::~AudioController()
{
    stop_listening_for_volume_changes();

    if (master_element_)
    {
        master_element_ = nullptr;
    }
    if (mixerHandle_)
    {
        snd_mixer_close(mixerHandle_);
        mixerHandle_ = nullptr;
    }
}

void AudioController::open_mixer()
{
    if (snd_mixer_open(&mixerHandle_, 0))
    {
        throw std::runtime_error("Failed to open mixer");
    }

    if (snd_mixer_attach(mixerHandle_, cardName_.c_str()))
    {
        snd_mixer_close(mixerHandle_);
        mixerHandle_ = nullptr;
        throw std::runtime_error("Failed to attach mixer to card: " + cardName_);
    }

    if (snd_mixer_selem_register(mixerHandle_, nullptr, nullptr))
    {
        snd_mixer_close(mixerHandle_);
        mixerHandle_ = nullptr;
        throw std::runtime_error("Failed to register mixer elements");
    }

    if (snd_mixer_load(mixerHandle_))
    {
        snd_mixer_close(mixerHandle_);
        mixerHandle_ = nullptr;
        throw std::runtime_error("Failed to load mixer controls");
    }

    snd_mixer_elem_t *elem = get_mixer_element("Master");
    if (elem)
    {
        master_element_ = elem;
    }
    else
    {
        std::cerr << "Failed to find master mixer element." << std::endl;
        throw std::runtime_error("Master mixer element not found");
    }
}

snd_mixer_elem_t *AudioController::get_mixer_element(const std::string &channel) const
{
    if (!mixerHandle_)
    {
        throw std::runtime_error("Mixer not open");
    }
    snd_mixer_selem_id_t *sid;
    snd_mixer_selem_id_alloca(&sid);
    snd_mixer_selem_id_set_name(sid, channel.c_str());

    snd_mixer_elem_t *elem = snd_mixer_find_selem(mixerHandle_, sid);
    if (!elem)
    {
        throw std::runtime_error("Unable to find mixer control: " + channel);
    }
    return elem;
}

double AudioController::get_volume()
{
    if (!master_element_)
    {
        throw std::runtime_error("Mixer or master element not initialized for get_volume");
    }

    // Handle events to ensure we have the latest state
    snd_mixer_handle_events(mixerHandle_);

    long min, max;
    snd_mixer_selem_get_playback_volume_range(master_element_, &min, &max);
    if (max - min == 0)
        return 0.0;

    long volume;
    if (snd_mixer_selem_get_playback_volume(master_element_, SND_MIXER_SCHN_FRONT_LEFT, &volume))
    {
        throw std::runtime_error("Failed to get volume for Master channel");
    }

    return (double)(volume - min) / (max - min);
}

void AudioController::set_volume(double volume_percent)
{
    double volume_decimal = volume_percent;

    if (!master_element_ && !mixerHandle_)
    {
        throw std::runtime_error("Mixer or master element not initialized for set_volume");
    }
    snd_mixer_elem_t *elem_to_use = master_element_;
    if (!elem_to_use)
    {
        throw std::runtime_error("Failed to get Master element for set_volume");
    }

    long min, max;
    snd_mixer_selem_get_playback_volume_range(elem_to_use, &min, &max);

    long rawVolume = min + (long)((max - min) * volume_decimal);

    if (snd_mixer_selem_set_playback_volume_all(elem_to_use, rawVolume))
    {
        throw std::runtime_error("Failed to set volume for Master channel");
    }
}

bool AudioController::is_muted()
{
    if (!master_element_ && !mixerHandle_)
    {
        throw std::runtime_error("Mixer or master element not initialized for is_muted");
    }
    snd_mixer_elem_t *elem_to_use = master_element_;
    if (!elem_to_use)
    {
        throw std::runtime_error("Failed to get Master element for is_muted");
    }

    int mute_state;
    if (snd_mixer_selem_get_playback_switch(elem_to_use, SND_MIXER_SCHN_FRONT_LEFT, &mute_state))
    {
        throw std::runtime_error("Failed to get mute state for Master channel");
    }

    return mute_state == 0;
}

void AudioController::set_mute(bool mute)
{
    if (!master_element_ && !mixerHandle_)
    {
        throw std::runtime_error("Mixer or master element not initialized for set_mute");
    }
    snd_mixer_elem_t *elem_to_use = master_element_;
    if (!elem_to_use)
    {
        throw std::runtime_error("Failed to get Master element for set_mute");
    }

    if (snd_mixer_selem_set_playback_switch_all(elem_to_use, mute ? 0 : 1))
    {
        throw std::runtime_error("Failed to set mute state for Master channel");
    }
}

void AudioController::check_volume_and_notify()
{
    if (!master_element_ || !volume_change_callback_)
    {
        return;
    }

    double volume = get_volume();

    if (last_known_volume_ != volume)
    {
        last_known_volume_ = volume;
        volume_change_callback_(volume, callback_user_data_);
    }
}

gpointer AudioController::volume_listener_thread_func_static(gpointer data)
{
    AudioController *self = static_cast<AudioController *>(data);
    self->volume_listener_loop();
    return nullptr;
}

void AudioController::volume_listener_loop()
{
    bool fetch_initial_volume = this->fetch_initial_volume;
    bool check_volume_and_notify_called = false;
    double initial_volume = get_volume();

    if (fetch_initial_volume)
    {
        check_volume_and_notify_called = true;
    }

    while (listening_for_volume_changes_)
    {
        if (!listening_for_volume_changes_)
        {
            break;
        }

        if (check_volume_and_notify_called)
        {
            check_volume_and_notify();
        }
        else if (initial_volume != get_volume())
        {
            check_volume_and_notify_called = true;
            check_volume_and_notify();
        }

        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}

bool AudioController::start_listening_for_volume_changes(VolumeChangeCallback callback, gpointer user_data)
{
    if (listening_for_volume_changes_)
    {
        return true;
    }

    volume_change_callback_ = callback;
    callback_user_data_ = user_data;
    listening_for_volume_changes_ = true;

    GError *error = nullptr;
    volume_listener_thread_ = g_thread_try_new("volume-listener", volume_listener_thread_func_static, this, &error);
    if (!volume_listener_thread_)
    {
        std::cerr << "Failed to create volume listener thread: " << (error ? error->message : "Unknown error") << std::endl;
        if (error)
            g_error_free(error);
        listening_for_volume_changes_ = false;
        return false;
    }

    return true;
}

void AudioController::stop_listening_for_volume_changes()
{
    if (!listening_for_volume_changes_)
    {
        return;
    }

    listening_for_volume_changes_ = false;

    if (volume_listener_thread_)
    {
        g_thread_join(volume_listener_thread_);
        volume_listener_thread_ = nullptr;
    }
}

