    flutter::PluginRegistrarWindows *registrar) {

  static bool initialized = false;
  if (!initialized) {
    super_native_extensions_init();
    initialized = true;
  }

  auto plugin = std::make_unique<SuperNativeExtensionsPlugin>();

  registrar->AddPlugin(std::move(plugin));
}

